{"command":"cat > /tmp/harness.py <<'PY'
import subprocess, time, os, sys
SESS="pecotest"
def tmux(*args):
    return subprocess.run(["tmux"]+list(args), capture_output=True, text=True)
def kill():
    tmux("kill-session","-t",SESS)
def start(cmd, w=80,h=24, env=None):
    kill()
    for f in ["/tmp/out.txt","/tmp/err.txt"]:
        try: os.remove(f)
        except: pass
    full = cmd+"; echo EXIT:$? >>/tmp/out.txt; sleep 1000"
    if env:
        prefix=" ".join(f"{k}={v}" for k,v in env.items())+" "
        full=prefix+full
    tmux("new-session","-d","-s",SESS,"-x",str(w),"-y",str(h),"-c","/workspace", full)
    time.sleep(0.8)
def cap(e=False, trim=True):
    args=["capture-pane","-t",SESS,"-p"]
    if e: args.append("-e")
    r=tmux(*args)
    s=r.stdout
    if trim:
        lines=s.rstrip("\n").split("\n")
        # remove trailing empty
        while lines and lines[-1]=="":
            lines.pop()
        return "\n".join(lines)
    return s
def send(*keys):
    tmux("send-keys","-t",SESS,*keys)
    time.sleep(0.3)
def lit(s):
    # send literal via tmux send-keys -l one char sequence? use list
    tmux("send-keys","-t",SESS,"-l",s)
    time.sleep(0.3)
def out():
    try: return open("/tmp/out.txt").read()
    except: return "<no out>"
def err():
    try: return open("/tmp/err.txt").read()
    except: return "<no err>"
def show(label=""):
    print(f"--- {label} ---")
    print(cap())
PY
