def decode_seq(s):
    attrs={"fg":None,"bg":None,"bold":False,"underline":False,"reverse":False}
    lines=[]
    cur=""; curattr=None; out=[]
    toks=re.split(r'(\x1b\[[0-9;]*m|\n)', s)
