import itertools
# trajectories: (start_index 0based, moves list of +1/-1, observed final set)
cases=[
 (0,[1,1],{0,1,2}),
 (0,[1,1,-1],{0}),
 (0,[1],{0,1}),
 (0,[1,-1],{0}),
 (2,[-1,-1],{0,1,2}),
 (2,[-1],{1,2}),
 (2,[-1,1],{2}),
 (2,[-1,-1,1],{1,2}),
 (0,[1,1,1,-1,-1],{0}),
 (4,[],{4}),
 (2,[1,1],{2,3,4}),
]
ops=["add","remove","none","toggle"]
def apply(s,i,op):
    if op=="add": s.add(i)
    elif op=="remove": s.discard(i)
    elif op=="toggle":
        if i in s: s.remove(i)
        else: s.add(i)
def sim(start,moves,entry,down_dep,down_arr,up_dep,up_arr,exit_op):
    s=set()
    cur=start
    apply(s,cur,entry)
    for m in moves:
        if m==1: dep,arr=down_dep,down_arr
        else: dep,arr=up_dep,up_arr
        apply(s,cur,dep)
        cur+=m
        apply(s,cur,arr)
    # exit_op here means ToggleOff/Finish action on current? apply
    apply(s,cur,exit_op)
    # Finish fallback: if s empty, output current (we need account: mark in check separately?)
    return s
sols=[]
for entry in ops+["add"]: # entry likely add/none
 for dd in ops:
  for da in ops:
   for ud in ops:
    for ua in ops:
     for ex in ops:
        ok=True
        for start,moves,obs in cases:
            s=sim(start,moves,entry,dd,da,ud,ua,ex)
            # if empty, finish outputs current
            if not s: s={start+sum(moves)}
            if s!=obs: ok=False; break
        if ok: sols.append((entry,dd,da,ud,ua,ex))
print("solutions", sols[:50], len(sols))
