		if len(t) > 0 {
			switch {
			case t[0] >= '0' && t[0] <= '9' || t[0] == '-':
				v = "number"
			case t[0] == 't' || t[0] == 'f':
				v = "bool"
			case t[0] == '[':
				v = "array"
			case t[0] == '{':
				v = "object"
			}
		}
		_ = ute
		return &json.UnmarshalTypeError{Value: v, Type: reflect.TypeOf(OnCancelBehavior(""))}
	}
	v, err := validateOnCancel(s)
	if err != nil {
		return err
	}
	*o = v
	return nil
}

type SingleKeyJumpConfig struct {
	ShowPrefix bool
}

type CustomFilterConfig struct {
	Cmd             string
	Args            []string
	BufferThreshold int
}

// StyleSet stores the raw style definitions from a configuration file.
// The individual fields are lists of style tokens.
type StyleSet struct {
	Basic          []string
	SavedSelection []string
	Selected       []string
	Query          []string
	QueryCursor    []string
	Matched        []string
	Prompt         []string
	Context        []string

	// Present records which keys were explicitly present.
	Present map[string]bool `json:"-"`
}

var styleFieldNames = []string{
	"Basic", "SavedSelection", "Selected", "Query", "QueryCursor", "Matched", "Prompt", "Context",
}

func (ss *StyleSet) setField(name string, v []string) {
	switch name {
	case "Basic":
		ss.Basic = v
	case "SavedSelection":
		ss.SavedSelection = v
	case "Selected":
		ss.Selected = v
	case "Query":
		ss.Query = v
	case "QueryCursor":
		ss.QueryCursor = v
	case "Matched":
		ss.Matched = v
	case "Prompt":
		ss.Prompt = v
	case "Context":
		ss.Context = v
	}
}

func (ss *StyleSet) UnmarshalJSON(data []byte) error {
	trimmed := bytes.TrimSpace(data)
	if len(trimmed) == 0 || trimmed[0] != '{' {
		v := "value"
		if len(trimmed) > 0 {
			switch {
			case trimmed[0] == '"':
				v = "string"
			case trimmed[0] >= '0' && trimmed[0] <= '9' || trimmed[0] == '-':
				v = "number"
			case trimmed[0] == '[':
				v = "array"
			case trimmed[0] == 't' || trimmed[0] == 'f':
				v = "bool"
			}
		}
		return &json.UnmarshalTypeError{Value: v, Type: reflect.TypeOf(StyleSet{})}
	}
	var raw map[string]json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		return &json.UnmarshalTypeError{Value: "object", Type: reflect.TypeOf(StyleSet{})}
	}
	if ss.Present == nil {
		ss.Present = make(map[string]bool)
	}
	for _, name := range styleFieldNames {
		rv, ok := raw[name]
		if !ok {
			// encoding/json matches keys case-insensitively; emulate
			// that for the known style keys.
			for k, v := range raw {
				if strings.EqualFold(k, name) {
					rv, ok = v, true
					break
				}
			}
		}
		if !ok {
			continue
		}
		var list []string
		if err := json.Unmarshal(rv, &list); err != nil {
			return fmt.Errorf("failed to unmarshal Style: %w", err)
		}
		ss.Present[name] = true
		ss.setField(name, list)
	}
	return nil
}

// Config mirrors the JSON/YAML configuration file structure.
type Config struct {
	Prompt             string
	InitialFilter      string
	FuzzyLongestSort   bool
	StickySelection    bool
	SuppressStatusMsg  bool
	OnCancel           OnCancelBehavior
	MaxScanBufferSize  int
	ANSI               bool
	Height             string
	Layout             string
	Keymap             map[string]string
	Style              StyleSet
	CustomFilter       map[string]CustomFilterConfig
	SingleKeyJump      SingleKeyJumpConfig
	SelectionPrefix    string
	Action             map[string][]string
}

func validLayout(s string) bool {
	switch s {
	case "", "top-down", "bottom-up", "top-down-query-bottom":
		return true
	}
	return false
}

// ReadFile reads and parses a configuration file. The decoding format is
// chosen from the filename extension: .yaml/.yml are YAML, everything
// else is treated as JSON.
func ReadFile(filename string) (*Config, error) {
	f, err := os.Open(filename)
	if err != nil {
		return nil, fmt.Errorf("failed to open file %s: %w", filename, err)
	}
	defer f.Close()
	data, err := readAll(f)
	if err != nil {
		// For JSON files the read error surfaces from the decoder, to
		// match the messages produced by json.Decoder.
		ext := strings.ToLower(filepath.Ext(filename))
		if ext == ".yaml" || ext == ".yml" {
			return nil, fmt.Errorf("failed to decode YAML: %w", err)
		}
		return nil, fmt.Errorf("failed to decode JSON: %w", err)
	}
	cfg, err := decodeConfigBytes(filename, data)
	if err != nil {
		return nil, err
	}
	if !validLayout(cfg.Layout) {
		return nil, fmt.Errorf("invalid layout type: %s", cfg.Layout)
	}
	return cfg, nil
}

func readAll(f *os.File) ([]byte, error) {
	var buf bytes.Buffer
	_, err := buf.ReadFrom(f)
	if err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

func decodeConfigBytes(filename string, data []byte) (*Config, error) {
	ext := filepath.Ext(filename)
	if ext == ".yaml" || ext == ".yml" {
		cfg, err := decodeYAML(data)
		if err != nil {
			return nil, fmt.Errorf("failed to decode YAML: %w", err)
		}
		return cfg, nil
	}
	var cfg Config
	dec := json.NewDecoder(bytes.NewReader(data))
	if err := dec.Decode(&cfg); err != nil {
		return nil, fmt.Errorf("failed to decode JSON: %w", err)
	}
	return &cfg, nil
}

// Locate finds the configuration file to use, following the documented
// search order. It returns an empty string when no file exists.
func Locate() string {
	type candidate struct{ dir string }
	var dirs []string
	if x := os.Getenv("XDG_CONFIG_HOME"); x != "" {
		dirs = append(dirs, x)
	} else if home := os.Getenv("HOME"); home != "" {
		dirs = append(dirs, filepath.Join(home, ".config"))
	}
	if x := os.Getenv("XDG_CONFIG_DIRS"); x != "" {
		for _, d := range filepath.SplitList(x) {
			if d != "" {
				dirs = append(dirs, d)
			}
		}
	} else {
		dirs = append(dirs, "/etc/xdg")
	}
	exts := []string{".json", ".yaml", ".yml"}
	for _, dir := range dirs {
		for _, ext := range exts {
			p := filepath.Join(dir, "peco", "config"+ext)
			if _, err := os.Stat(p); err == nil {
				return p
			}
		}
	}
	if home := os.Getenv("HOME"); home != "" {
		for _, ext := range exts {
			p := filepath.Join(home, ".peco", "config"+ext)
			if _, err := os.Stat(p); err == nil {
				return p
			}
		}
	}
	return ""
}

