cat > config/yaml.go <<'EOF'
package config

import (
	"fmt"
	"strconv"
	"strings"
)

// This is a small YAML decoder covering the subset of YAML that can
// sensibly appear in a peco configuration file: block and flow mappings,
// block and flow sequences, quoted and plain scalars, comments and a
// single document. It exists to avoid a hard dependency on a full YAML
// library while preserving peco's configuration semantics.

type yamlKind int

const (
	yamlNull yamlKind = iota
	yamlString
	yamlInt
	yamlFloat
	yamlBool
	yamlMap
	yamlSeq
)

type yamlPair struct {
	key *yamlNode
	val *yamlNode
}

type yamlNode struct {
	kind  yamlKind
	text  string // scalar text (canonicalised for bools)
	raw   string // original scalar text
	pairs []yamlPair
	items []*yamlNode
	line  int
	col   int
}

func (n *yamlNode) typeName() string {
	switch n.kind {
	case yamlNull:
		return "null"
	case yamlString:
		return "string"
	case yamlInt:
		// goccy-style naming: non-negative integers decode as uint64.
		if strings.HasPrefix(n.text, "-") {
			return "int"
		}
		return "uint64"
	case yamlFloat:
		return "float64"
	case yamlBool:
		return "bool"
	case yamlMap:
		return "mapping"
	case yamlSeq:
		return "sequence"
	}
	return "value"
}

type yamlError struct {
	line, col int
	msg       string
	src       []string
}

func (e *yamlError) Error() string {
	var b strings.Builder
	fmt.Fprintf(&b, "[%d:%d] %s\n", e.line, e.col, e.msg)
	start := e.line - 1
	if start < 1 {
		start = 1
	}
	end := e.line + 1
	if end > len(e.src) {
		end = len(e.src)
	}
	for i := start; i <= end; i++ {
		prefix := "   "
		if i == e.line {
			prefix = ">  "
		}
		fmt.Fprintf(&b, "%s%d | %s\n", prefix, i, e.src[i-1])
		if i == e.line {
			caretPad := 7 + (e.col - 1)
			// Account for multi-digit line numbers in the gutter.
			caretPad = len(fmt.Sprintf("%s%d | ", prefix, i)) + (e.col - 1)
			b.WriteString(strings.Repeat(" ", caretPad) + "^\n")
		}
	}
	return b.String()
}

func srcLines(data []byte) []string {
	s := strings.ReplaceAll(string(data), "\r\n", "\n")
	lines := strings.Split(s, "\n")
	if len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
	}
	if len(lines) == 0 {
		lines = []string{""}
	}
	return lines
}

// ---------------- lexer helpers ----------------

func isCommentOrBlank(s string) bool {
	t := strings.TrimSpace(s)
	return t == "" || strings.HasPrefix(t, "#")
}

func stripComment(s string) string {
	// A '#' starting a comment must be preceded by whitespace (or be at
	// the start). Quoted sections are handled by callers that scan.
	inS, inD := false, false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inD {
			if c == '\\' {
				i++
			} else if c == '"' {
				inD = false
			}
			continue
		}
		if inS {
			if c == '\'' {
				inS = false
			}
			continue
		}
		switch c {
		case '\'':
			inS = true
		case '"':
			inD = true
		case '#':
			if i == 0 || s[i-1] == ' ' || s[i-1] == '\t' {
				return strings.TrimRight(s[:i], " \t")
			}
		}
	}
	return s
}

// ---------------- parser ----------------

type yamlParser struct {
	lines []string
	pos   int
}

func decodeYAML(data []byte) (*Config, error) {
	lines := srcLines(data)
	// Check for a completely empty document.
	nonEmpty := false
	for _, l := range lines {
		if !isCommentOrBlank(l) {
			nonEmpty = true
			break
		}
	}
	if !nonEmpty {
		return nil, fmt.Errorf("EOF")
	}
	p := &yamlParser{lines: lines}
	root, err := p.parseDocument()
	if err != nil {
		return nil, err
	}
	if root == nil {
		return nil, fmt.Errorf("EOF")
	}
	if root.kind == yamlNull {
		// A lone "null" still counts as a type error, but a null from
		// an explicit "~" is the same node kind; goccy reports it.
		// Only the literal bare-document null reaches here.
		return nil, &yamlError{line: root.line, col: root.col, msg: "null was used where mapping is expected", src: lines}
	}
	if root.kind != yamlMap {
		return nil, &yamlError{line: root.line, col: root.col, msg: fmt.Sprintf("%s was used where mapping is expected", root.typeName()), src: lines}
	}
	cfg := &Config{}
	if err := cfg.applyYAMLMap(root, lines); err != nil {
		return nil, err
	}
	return cfg, nil
}

func (p *yamlParser) parseDocument() (*yamlNode, error) {
	// Skip blank/comment lines and a document-start marker.
	for p.pos < len(p.lines) {
		t := strings.TrimSpace(p.lines[p.pos])
		if t == "" || strings.HasPrefix(t, "#") || t == "---" {
			p.pos++
			continue
		}
		break
	}
	if p.pos >= len(p.lines) {
		return nil, nil
	}
	node, err := p.parseBlock(indentOf(p.lines[p.pos]))
	if err != nil {
		return nil, err
	}
	return node, nil
}

func indentOf(s string) int {
	n := 0
	for n < len(s) && s[n] == ' ' {
		n++
	}
	return n
}

// parseBlock parses a block structure whose entries sit at the given
// indent. It consumes lines as needed.
func (p *yamlParser) parseBlock(indent int) (*yamlNode, error) {
	// Find the first content line.
	for p.pos < len(p.lines) && isCommentOrBlank(p.lines[p.pos]) {
		p.pos++
	}
	if p.pos >= len(p.lines) {
		return &yamlNode{kind: yamlNull, text: "null", line: len(p.lines), col: 1}, nil
	}
	raw := p.lines[p.pos]
	if indentOf(raw) < indent {
		return &yamlNode{kind: yamlNull, text: "null", line: p.pos + 1, col: 1}, nil
	}
	content := strings.TrimSpace(stripComment(raw))
	if content == "..." {
		p.pos++
		return &yamlNode{kind: yamlNull, text: "null", line: p.pos, col: 1}, nil
	}
	// A second document start means the first document ended.
	if content == "---" {
		return &yamlNode{kind: yamlNull, text: "null", line: p.pos + 1, col: 1}, nil
	}
	if strings.HasPrefix(content, "- ") || content == "-" {
		return p.parseBlockSeq(indent)
	}
	// Mapping or a scalar/flow value occupying the whole block.
	if key, rest, ok := splitKey(content); ok {
		_ = key
		_ = rest
		return p.parseBlockMap(indent)
	}
	// Lone scalar (possibly flow).
	lineNo := p.pos + 1
	node, err := parseFlowOrScalar(content, lineNo, indent+1, p.lines)
	if err != nil {
		return nil, err
	}
	p.pos++
	return node, nil
}

func splitKey(content string) (string, string, bool) {
	// Find a ": " or trailing ":" at the top level (not inside quotes
	// or flow collections).
	inS, inD := false, false
	depth := 0
	for i := 0; i < len(content); i++ {
		c := content[i]
		if inD {
			if c == '\\' {
				i++
			} else if c == '"' {
				inD = false
			}
			continue
		}
		if inS {
			if c == '\'' {
				inS = false
			}
			continue
		}
		switch c {
		case '\'':
			inS = true
		case '"':
			inD = true
		case '[', '{':
			depth++
		case ']', '}':
			depth--
		case ':':
			if depth == 0 {
				if i == len(content)-1 {
					return content[:i], "", true
				}
				if content[i+1] == ' ' {
					return content[:i], strings.TrimSpace(content[i+2:]), true
				}
			}
		}
	}
	return "", "", false
}

func (p *yamlParser) parseBlockMap(indent int) (*yamlNode, error) {
	node := &yamlNode{kind: yamlMap, line: p.pos + 1, col: indent + 1}
	seen := make(map[string][2]int) // key -> line,col of first definition
	for p.pos < len(p.lines) {
		raw := p.lines[p.pos]
		if isCommentOrBlank(raw) {
			p.pos++
			continue
		}
		ind := indentOf(raw)
		if ind < indent {
			break
		}
		if ind > indent {
			// Should have been consumed by a nested value; skip.
			p.pos++
			continue
		}
		content := strings.TrimSpace(stripComment(raw))
		if content == "---" || content == "..." {
			break
		}
		if strings.HasPrefix(content, "- ") || content == "-" {
			break
		}
		keyStr, rest, ok := splitKey(content)
		if !ok {
			break
		}
		lineNo := p.pos + 1
		keyNode, err := parseFlowOrScalar(strings.TrimSpace(keyStr), lineNo, indent+1, p.lines)
		if err != nil {
			return nil, err
		}
		keyText := keyNode.text
		if first, dup := seen[keyText]; dup {
			return nil, &yamlError{line: lineNo, col: indent + 1, msg: fmt.Sprintf("mapping key %q already defined at [%d:%d]", keyText, first[0], first[1]), src: p.lines}
		}
		seen[keyText] = [2]int{lineNo, indent + 1}
		keyCol := indent + 1
		_ = keyCol
		p.pos++
		var val *yamlNode
		if rest == "" {
			// Value is a nested block, an indented sequence, or null.
			// Look at the next content line.
			save := p.pos
			for p.pos < len(p.lines) && isCommentOrBlank(p.lines[p.pos]) {
				p.pos++
			}
			if p.pos >= len(p.lines) {
				val = &yamlNode{kind: yamlNull, text: "null", line: lineNo, col: indent + 1}
			} else {
				nextRaw := p.lines[p.pos]
				nextInd := indentOf(nextRaw)
				nextContent := strings.TrimSpace(stripComment(nextRaw))
				if nextInd <= indent && !(strings.HasPrefix(nextContent, "- ") || nextContent == "-") {
					// No nested value.
					p.pos = save
					val = &yamlNode{kind: yamlNull, text: "null", line: lineNo, col: indent + 1}
				} else if strings.HasPrefix(nextContent, "- ") || nextContent == "-" {
					// Block sequences may sit at the same indent as
					// the key.
					v, err := p.parseBlockSeq(nextInd)
					if err != nil {
						return nil, err
					}
					val = v
				} else if nextInd > indent {
					v, err := p.parseBlock(nextInd)
					if err != nil {
						return nil, err
					}
					val = v
				} else {
					p.pos = save
					val = &yamlNode{kind: yamlNull, text: "null", line: lineNo, col: indent + 1}
				}
			}
		} else if rest == "|" || rest == ">" || rest == "|-" || rest == ">-" || rest == "|+" || rest == ">+" {
			// Block scalars: gather indented lines.
			folded := strings.HasPrefix(rest, ">")
			var parts []string
			baseInd := -1
			for p.pos < len(p.lines) {
				l := p.lines[p.pos]
				if strings.TrimSpace(l) == "" {
					parts = append(parts, "")
					p.pos++
					continue
				}
				ind := indentOf(l)
				if ind <= indent {
					break
				}
				if baseInd == -1 {
					baseInd = ind
				}
				if ind < baseInd {
					break
				}
				parts = append(parts, l[baseInd:])
				p.pos++
			}
			// Trim trailing blank lines gathered speculatively.
			for len(parts) > 0 && parts[len(parts)-1] == "" {
				parts = parts[:len(parts)-1]
			}
			sep := "\n"
			if folded {
				sep = " "
			}
			val = &yamlNode{kind: yamlString, text: strings.Join(parts, sep) + "\n", raw: rest, line: lineNo, col: indent + len(keyStr) + 3}
		} else {
			// Value on the same line: could itself be a flow node
			// spanning multiple lines in principle; we support
			// balancing brackets across following lines.
			valText := rest
			valCol := indent + len(keyStr) + 3 // 1-based col of value approx
			// Compute the exact column of rest within the raw line.
			if idx := strings.Index(raw, rest); idx >= 0 {
				valCol = idx + 1
			}
			for (strings.Count(valText, "[") > strings.Count(valText, "]") || strings.Count(valText, "{") > strings.Count(valText, "}")) && p.pos < len(p.lines) {
				valText += "\n" + strings.TrimSpace(stripComment(p.lines[p.pos]))
				p.pos++
			}
			v, err := parseFlowOrScalar(valText, lineNo, valCol, p.lines)
			if err != nil {
				return nil, err
			}
			// A value like "a\n  b: c" (nested block map written on
			// the following lines after a plain scalar) is not valid
			// for our purposes; scalar values end here.
			val = v
		}
		node.pairs = append(node.pairs, yamlPair{key: keyNode, val: val})
	}
	return node, nil
}

func (p *yamlParser) parseBlockSeq(indent int) (*yamlNode, error) {
	node := &yamlNode{kind: yamlSeq, line: p.pos + 1, col: indent + 1}
	for p.pos < len(p.lines) {
		raw := p.lines[p.pos]
		if isCommentOrBlank(raw) {
			p.pos++
			continue
		}
		ind := indentOf(raw)
		if ind != indent {
			break
		}
		content := strings.TrimSpace(stripComment(raw))
		if content != "-" && !strings.HasPrefix(content, "- ") {
			break
		}
		lineNo := p.pos + 1
		rest := strings.TrimSpace(strings.TrimPrefix(content, "-"))
		itemCol := ind + 3
		p.pos++
		if rest == "" {
			// Nested block under the dash.
			save := p.pos
			for p.pos < len(p.lines) && isCommentOrBlank(p.lines[p.pos]) {
				p.pos++
			}
			if p.pos < len(p.lines) && indentOf(p.lines[p.pos]) > indent {
				v, err := p.parseBlock(indentOf(p.lines[p.pos]))
				if err != nil {
					return nil, err
				}
				node.items = append(node.items, v)
			} else {
				p.pos = save
				node.items = append(node.items, &yamlNode{kind: yamlNull, text: "null", line: lineNo, col: itemCol})
			}
			continue
		}
		if _, _, isMap := splitKey(rest); isMap {
			// A mapping starting on the dash line: treat the rest of
			// this line as a one-line map entry plus following
			// deeper-indented entries. Approximate by building a
			// synthetic map parse: rewind one line and parse a block
			// map at the dash-item indent + 2.
			p.pos--
			// Rewrite is complex; fall back to a map of that single
			// pair (config files do not use this form).
			m := &yamlNode{kind: yamlMap, line: lineNo, col: itemCol}
			k, r, _ := splitKey(rest)
			kn, _ := parseFlowOrScalar(strings.TrimSpace(k), lineNo, itemCol, p.lines)
			var vn *yamlNode
			if r == "" {
				vn = &yamlNode{kind: yamlNull, text: "null", line: lineNo, col: itemCol}
			} else {
				vv, err := parseFlowOrScalar(r, lineNo, itemCol, p.lines)
				if err != nil {
					return nil, err
				}
				vn = vv
			}
			m.pairs = append(m.pairs, yamlPair{key: kn, val: vn})
			p.pos++
			node.items = append(node.items, m)
			continue
		}
		v, err := parseFlowOrScalar(rest, lineNo, itemCol, p.lines)
		if err != nil {
			return nil, err
		}
		node.items = append(node.items, v)
	}
	return node, nil
}

// parseFlowOrScalar parses a flow collection or a scalar token.
func parseFlowOrScalar(s string, line, col int, src []string) (*yamlNode, error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return &yamlNode{kind: yamlNull, text: "null", line: line, col: col}, nil
	}
	switch s[0] {
	case '[':
		if !strings.HasSuffix(s, "]") {
			return nil, &yamlError{line: line, col: col + len(s) - 1, msg: "sequence end token ']' not found", src: src}
		}
		node := &yamlNode{kind: yamlSeq, line: line, col: col}
		inner := strings.TrimSpace(s[1 : len(s)-1])
		if inner != "" {
			parts, err := splitFlow(inner)
			if err != nil {
				return nil, &yamlError{line: line, col: col, msg: err.Error(), src: src}
			}
			for _, part := range parts {
				v, err := parseFlowOrScalar(part, line, col, src)
				if err != nil {
					return nil, err
				}
				node.items = append(node.items, v)
			}
		}
		return node, nil
	case '{':
		if !strings.HasSuffix(s, "}") {
			return nil, &yamlError{line: line, col: col, msg: "mapping end token '}' not found", src: src}
		}
		node := &yamlNode{kind: yamlMap, line: line, col: col}
		inner := strings.TrimSpace(s[1 : len(s)-1])
		if inner != "" {
			parts, err := splitFlow(inner)
			if err != nil {
				return nil, &yamlError{line: line, col: col, msg: err.Error(), src: src}
			}
			for _, part := range parts {
				k, r, ok := splitKey(strings.TrimSpace(part))
				if !ok {
					// "key: value" without space after colon inside flow.
					if idx := strings.Index(part, ":"); idx >= 0 {
						k, r, ok = part[:idx], part[idx+1:], true
					}
				}
				if !ok {
					continue
				}
				kn, err := parseFlowOrScalar(strings.TrimSpace(k), line, col, src)
				if err != nil {
					return nil, err
				}
				vn, err := parseFlowOrScalar(strings.TrimSpace(r), line, col, src)
				if err != nil {
					return nil, err
				}
				node.pairs = append(node.pairs, yamlPair{key: kn, val: vn})
			}
		}
		return node, nil
	case '\'':
		if len(s) < 2 || !strings.HasSuffix(s, "'") {
			return nil, &yamlError{line: line, col: col, msg: "could not find end character of single-quoted text", src: src}
		}
		return &yamlNode{kind: yamlString, text: strings.ReplaceAll(s[1:len(s)-1], "''", "'"), raw: s, line: line, col: col}, nil
	case '"':
		if len(s) < 2 || !strings.HasSuffix(s, "\"") {
			return nil, &yamlError{line: line, col: col, msg: "could not find end character of double-quoted text", src: src}
		}
		unq, err := strconv.Unquote(s)
		if err != nil {
			// Fall back to a lenient unescape.
			unq = s[1 : len(s)-1]
		}
		return &yamlNode{kind: yamlString, text: unq, raw: s, line: line, col: col}, nil
	}
	return resolvePlainScalar(s, line, col), nil
}

func splitFlow(s string) ([]string, error) {
	var parts []string
	depth := 0
	inS, inD := false, false
	start := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inD {
			if c == '\\' {
				i++
			} else if c == '"' {
				inD = false
			}
			continue
		}
		if inS {
			if c == '\'' {
				inS = false
			}
			continue
		}
		switch c {
		case '\'':
			inS = true
		case '"':
			inD = true
		case '[', '{':
			depth++
		case ']', '}':
			depth--
		case ',':
			if depth == 0 {
				parts = append(parts, strings.TrimSpace(s[start:i]))
				start = i + 1
			}
		}
	}
	parts = append(parts, strings.TrimSpace(s[start:]))
	return parts, nil
}

func resolvePlainScalar(s string, line, col int) *yamlNode {
	switch s {
	case "null", "Null", "NULL", "~":
		return &yamlNode{kind: yamlNull, text: "null", raw: s, line: line, col: col}
	case "true", "True", "TRUE":
		return &yamlNode{kind: yamlBool, text: "true", raw: s, line: line, col: col}
	case "false", "False", "FALSE":
		return &yamlNode{kind: yamlBool, text: "false", raw: s, line: line, col: col}
	}
	if v, err := strconv.ParseInt(s, 0, 64); err == nil {
		_ = v
		return &yamlNode{kind: yamlInt, text: s, raw: s, line: line, col: col}
	}
	if _, err := strconv.ParseUint(s, 10, 64); err == nil {
		return &yamlNode{kind: yamlInt, text: s, raw: s, line: line, col: col}
	}
	if _, err := strconv.ParseFloat(s, 64); err == nil && looksNumeric(s) {
		return &yamlNode{kind: yamlFloat, text: s, raw: s, line: line, col: col}
	}
	return &yamlNode{kind: yamlString, text: s, raw: s, line: line, col: col}
}

func looksNumeric(s string) bool {
	if s == "" {
		return false
	}
	c := s[0]
	return (c >= '0' && c <= '9') || c == '-' || c == '+' || c == '.'
}

// ---------------- decoding into Config ----------------

func (c *Config) applyYAMLMap(root *yamlNode, src []string) error {
	for _, pair := range root.pairs {
		key := pair.key.text
		val := pair.val
		var err error
		switch key {
		case "Prompt":
			err = assignYAMLString(&c.Prompt, val, src, "Config.Prompt")
		case "InitialFilter":
			err = assignYAMLString(&c.InitialFilter, val, src, "Config.InitialFilter")
		case "FuzzyLongestSort":
			err = assignYAMLBool(&c.FuzzyLongestSort, val, src, "Config.FuzzyLongestSort")
		case "StickySelection":
			err = assignYAMLBool(&c.StickySelection, val, src, "Config.StickySelection")
		case "SuppressStatusMsg":
			err = assignYAMLBool(&c.SuppressStatusMsg, val, src, "Config.SuppressStatusMsg")
		case "OnCancel":
			if val.kind == yamlNull {
				break
			}
			s := scalarToString(val)
			v, verr := validateOnCancel(s)
			if verr != nil {
				return verr
			}
			c.OnCancel = v
		case "MaxScanBufferSize":
			err = assignYAMLInt(&c.MaxScanBufferSize, val, src, "Config.MaxScanBufferSize")
		case "ANSI":
			err = assignYAMLBool(&c.ANSI, val, src, "Config.ANSI")
		case "Height":
			err = assignYAMLString(&c.Height, val, src, "Config.Height")
		case "Layout":
			err = assignYAMLString(&c.Layout, val, src, "Config.Layout")
		case "SelectionPrefix":
			err = assignYAMLString(&c.SelectionPrefix, val, src, "Config.SelectionPrefix")
		case "Keymap":
			m, merr := yamlStringMap(val, src)
			if merr != nil {
				return merr
			}
			c.Keymap = m
		case "Action":
			if val.kind == yamlNull {
				break
			}
			if val.kind != yamlMap {
				return &yamlError{line: val.line, col: val.col, msg: fmt.Sprintf("%s was used where mapping is expected", val.typeName()), src: src}
			}
			m := make(map[string][]string)
			for _, p := range val.pairs {
				list, lerr := yamlStringList(p.val, src)
				if lerr != nil {
					return lerr
				}
				m[p.key.text] = list
			}
			c.Action = m
		case "Style":
			if val.kind == yamlNull {
				break
			}
			if val.kind != yamlMap {
				return &yamlError{line: val.line, col: val.col, msg: fmt.Sprintf("%s was used where mapping is expected", val.typeName()), src: src}
			}
			if c.Style.Present == nil {
				c.Style.Present = make(map[string]bool)
			}
			for _, p := range val.pairs {
				known := false
				for _, name := range styleFieldNames {
					if p.key.text == name {
						known = true
						break
					}
				}
				if !known {
					continue
				}
				if p.val.kind != yamlSeq {
					return fmt.Errorf("failed to unmarshal Style from YAML: %w", &yamlError{line: p.val.line, col: p.val.col, msg: fmt.Sprintf("%s was used where sequence is expected", p.val.typeName()), src: src})
				}
				var list []string
				for _, it := range p.val.items {
					list = append(list, scalarToString(it))
				}
				c.Style.Present[p.key.text] = true
				c.Style.setField(p.key.text, list)
			}
		case "CustomFilter":
			if val.kind == yamlNull {
				break
			}
			if val.kind != yamlMap {
				return &yamlError{line: val.line, col: val.col, msg: fmt.Sprintf("%s was used where mapping is expected", val.typeName()), src: src}
			}
			m := make(map[string]CustomFilterConfig)
			for _, p := range val.pairs {
				var fc CustomFilterConfig
				if p.val.kind == yamlNull {
					m[p.key.text] = fc
					continue
				}
				if p.val.kind != yamlMap {
					return &yamlError{line: p.val.line, col: p.val.col, msg: fmt.Sprintf("%s was used where mapping is expected", p.val.typeName()), src: src}
				}
				for _, fp := range p.val.pairs {
					switch fp.key.text {
					case "Cmd":
						if err := assignYAMLString(&fc.Cmd, fp.val, src, "CustomFilterConfig.CustomFilter.Cmd"); err != nil {
							return err
						}
					case "Args":
						list, lerr := yamlStringList(fp.val, src)
						if lerr != nil {
							return lerr
						}
						fc.Args = list
					case "BufferThreshold":
						if err := assignYAMLInt(&fc.BufferThreshold, fp.val, src, "CustomFilterConfig.CustomFilter.BufferThreshold"); err != nil {
							return err
						}
					}
				}
				m[p.key.text] = fc
			}
			c.CustomFilter = m
		case "SingleKeyJump":
			if val.kind == yamlNull {
				break
			}
			if val.kind != yamlMap {
				return &yamlError{line: val.line, col: val.col, msg: fmt.Sprintf("%s was used where mapping is expected", val.typeName()), src: src}
			}
			for _, p := range val.pairs {
				if p.key.text == "ShowPrefix" {
					if err := assignYAMLBoolNested(&c.SingleKeyJump.ShowPrefix, p.val, src, "Config.SingleKeyJump"); err != nil {
						return err
					}
				}
			}
		default:
			// Unknown keys are ignored.
		}
		if err != nil {
			return err
		}
	}
	return nil
}

func scalarToString(n *yamlNode) string {
	if n == nil {
		return ""
	}
	switch n.kind {
	case yamlNull:
		return ""
	case yamlBool:
		return n.text
	default:
		return n.text
	}
}

func assignYAMLString(dst *string, n *yamlNode, src []string, field string) error {
	if n.kind == yamlNull {
		return nil
	}
	if n.kind == yamlMap || n.kind == yamlSeq {
		return &yamlError{line: n.line, col: n.col, msg: fmt.Sprintf("cannot unmarshal %s into Go struct field %s of type string", strings.TrimSuffix(n.typeName(), "ing"), field), src: src}
	}
	*dst = scalarToString(n)
	return nil
}

func assignYAMLBool(dst *bool, n *yamlNode, src []string, field string) error {
	if n.kind == yamlNull {
		return nil
	}
	if n.kind != yamlBool {
		return &yamlError{line: n.line, col: n.col, msg: fmt.Sprintf("cannot unmarshal %s into Go struct field %s of type bool", n.typeName(), field), src: src}
	}
	*dst = n.text == "true"
	return nil
}

func assignYAMLBoolNested(dst *bool, n *yamlNode, src []string, field string) error {
	return assignYAMLBool(dst, n, src, field)
}

func assignYAMLInt(dst *int, n *yamlNode, src []string, field string) error {
	if n.kind == yamlNull {
		return nil
	}
	switch n.kind {
	case yamlInt:
		if v, err := strconv.ParseInt(n.text, 0, 64); err == nil {
			*dst = int(v)
			return nil
		}
		if v, err := strconv.ParseUint(n.text, 10, 64); err == nil {
			*dst = int(v)
			return nil
		}
		return &yamlError{line: n.line, col: n.col, msg: fmt.Sprintf("cannot unmarshal %s into Go struct field %s of type int", n.typeName(), field), src: src}
	case yamlFloat:
		if v, err := strconv.ParseFloat(n.text, 64); err == nil {
			*dst = int(v)
			return nil
		}
	case yamlString:
		if v, err := strconv.ParseInt(strings.TrimSpace(n.text), 0, 64); err == nil {
			*dst = int(v)
			return nil
		}
		if v, err := strconv.ParseFloat(strings.TrimSpace(n.text), 64); err == nil {
			*dst = int(v)
			return nil
		}
	}
	return &yamlError{line: n.line, col: n.col, msg: fmt.Sprintf("cannot unmarshal %s into Go struct field %s of type int", n.typeName(), field), src: src}
}

func yamlStringMap(n *yamlNode, src []string) (map[string]string, error) {
	if n.kind == yamlNull {
		return nil, nil
	}
	if n.kind != yamlMap {
		return nil, &yamlError{line: n.line, col: n.col, msg: fmt.Sprintf("%s was used where mapping is expected", n.typeName()), src: src}
	}
	m := make(map[string]string)
	for _, p := range n.pairs {
		m[p.key.text] = scalarToString(p.val)
	}
	return m, nil
}

func yamlStringList(n *yamlNode, src []string) ([]string, error) {
	if n.kind == yamlNull {
		return nil, nil
	}
	if n.kind != yamlSeq {
		return nil, &yamlError{line: n.line, col: n.col, msg: fmt.Sprintf("%s was used where sequence is expected", n.typeName()), src: src}
	}
	var out []string
	for _, it := range n.items {
		out = append(out, scalarToString(it))
	}
	return out, nil
}
