				if s[j] == 'm' {
					cur = applySGR(cur, s[i+2:j])
				}
				i = j + 1
				continue
			}
			i++
			continue
		}
		r, size := utf8.DecodeRuneInString(s[i:])
		if r == utf8.RuneError && size == 1 {
			out = append(out, '?')
			styles = append(styles, cur)
			i++
			continue
		}
		out = append(out, r)
		styles = append(styles, cur)
		i += size
	}
	return string(out), styles
}

// applySGR applies an SGR parameter string to the current style.
func applySGR(cur styleDef, params string) styleDef {
	if params == "" {
		return styleDef{}
	}
	parts := strings.Split(params, ";")
	vals := make([]int, 0, len(parts))
	for _, p := range parts {
		if p == "" {
			vals = append(vals, 0)
			continue
		}
		n, err := parseSGRInt(p)
		if err != nil {
			// Unparseable parameters invalidate the rest.
			return cur
		}
		vals = append(vals, n)
	}
	for idx := 0; idx < len(vals); idx++ {
		v := vals[idx]
		switch {
		case v == 0:
			cur = styleDef{}
		case v == 1:
			cur.bold = true
		case v == 4:
			cur.underline = true
		case v == 7:
			cur.reverse = true
		case v >= 30 && v <= 37:
			cur.hasFg = true
			cur.fg = ansiBaseColor(v - 30)
		case v >= 40 && v <= 47:
			cur.hasBg = true
			cur.bg = ansiBaseColor(v - 40)
		case v == 38 || v == 48:
			isFg := v == 38
			if idx+1 < len(vals) && vals[idx+1] == 5 && idx+2 < len(vals) {
				c := paletteColor(vals[idx+2])
				if isFg {
					cur.hasFg, cur.fg = true, c
				} else {
					cur.hasBg, cur.bg = true, c
				}
				idx += 2
			} else if idx+1 < len(vals) && vals[idx+1] == 2 && idx+4 < len(vals) {
				c := rgbColor(vals[idx+2], vals[idx+3], vals[idx+4])
				if isFg {
					cur.hasFg, cur.fg = true, c
				} else {
					cur.hasBg, cur.bg = true, c
				}
				idx += 4
			}
		default:
			// Unsupported codes (2,3,5,9, bright colours, ...) are
			// ignored.
		}
	}
	return cur
}

func parseSGRInt(s string) (int, error) {
	n := 0
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return 0, errInvalidSGR
		}
		n = n*10 + int(s[i]-'0')
		if n > 1<<24 {
			return 0, errInvalidSGR
		}
	}
	if s == "" {
		return 0, nil
	}
	return n, nil
}

var errInvalidSGR = &sgrError{}

type sgrError struct{}

func (*sgrError) Error() string { return "invalid SGR" }
