// Line is a single selectable item.
type Line struct {
	id      int
	raw     string // original line as read (for custom results, the result line)
	display string // text used for matching and display
	output  string // text printed on selection

	displayRunes []rune
	offsets      []int // byte offset of each display rune
	ansiStyles   []styleDef
}

var nextLineID = 1

func allocLineID() int {
	id := nextLineID
	nextLineID++
	return id
}

// newLine builds a Line from a raw line, applying the global display
// options (NUL splitting and ANSI handling).
func newLine(raw string, nullSep bool, ansi bool) *Line {
	l := &Line{id: allocLineID(), raw: raw, output: raw}
	display := raw
	if nullSep {
		if idx := strings.IndexByte(raw, 0); idx >= 0 {
			display = raw[:idx]
			l.output = raw[idx+1:]
		}
	}
	l.display = makeDisplayText(display, ansi)
	if ansi {
		l.display, l.ansiStyles = parseANSIDisplay(display)
	}
	l.buildRunes()
	return l
}

// newInputLine is like newLine but keeps sequential ids in read order for
// ordinary input lines; it simply shares the global id counter.
func (l *Line) buildRunes() {
	l.displayRunes = nil
	l.offsets = nil
	s := l.display
	for i := 0; i < len(s); {
		r, size := utf8.DecodeRuneInString(s[i:])
		if r == utf8.RuneError && size == 1 {
			l.displayRunes = append(l.displayRunes, '?')
			l.offsets = append(l.offsets, i)
			i++
			continue
		}
		l.displayRunes = append(l.displayRunes, r)
		l.offsets = append(l.offsets, i)
		i += size
	}
	// Align ansi styles with display runes if present.
	if l.ansiStyles != nil && len(l.ansiStyles) != len(l.displayRunes) {
		// parseANSIDisplay already produces one style per rune of the
		// stripped text, which matches displayRunes except for invalid
		// bytes; pad/truncate defensively.
		for len(l.ansiStyles) < len(l.displayRunes) {
			l.ansiStyles = append(l.ansiStyles, styleDef{})
		}
		l.ansiStyles = l.ansiStyles[:len(l.displayRunes)]
	}
}

