	}
	return w
}

// isSpaceRune reports whether a rune separates words in the query editor.
func isSpaceRune(r rune) bool {
	return unicode.IsSpace(r)
}

// makeDisplayText strips escape sequences for display/matching when ANSI
// mode is off. CSI sequences with numeric parameters are removed,
// except extended-colour sequences (38;5/48;5/38;2/48;2), which are left
// as visible text (minus the ESC byte, which is dropped later).
func makeDisplayText(s string, ansi bool) string {
	if ansi {
		d, _ := parseANSIDisplay(s)
		return d
	}
	var b strings.Builder
	i := 0
	for i < len(s) {
		if s[i] == 0x1b && i+1 < len(s) && s[i+1] == '[' {
			j := i + 2
			for j < len(s) && isCSIFinal(s[j]) == false && (isCSIParam(s[j]) || isCSIIntermediate(s[j])) {
				j++
			}
			if j < len(s) && isCSIFinal(s[j]) {
				params := s[i+2 : j]
				if csiParamsAreNumeric(params) && !isExtendedColourCSI(params, s[j]) {
					// Strip the whole sequence.
					i = j + 1
					continue
				}
				// Leave the sequence text, minus ESC, to be
				// handled as ordinary runes; drop only ESC.
				i++ // skip ESC
				continue
			}
			// Unterminated: drop ESC.
			i++
			continue
		}
		b.WriteByte(s[i])
		i++
	}
	return b.String()
}

func isCSIParam(c byte) bool { return c >= 0x30 && c <= 0x3f }
func isCSIIntermediate(c byte) bool { return c >= 0x20 && c <= 0x2f }
func isCSIFinal(c byte) bool { return c >= 0x40 && c <= 0x7e }

func csiParamsAreNumeric(params string) bool {
	for i := 0; i < len(params); i++ {
		c := params[i]
		if !(c >= '0' && c <= '9' || c == ';' || c == ':') {
			return false
		}
	}
	return true
}

func isExtendedColourCSI(params string, final byte) bool {
	if final != 'm' {
		return false
	}
