			return true
		}
	}
	return false
}

// parseANSIDisplay strips all CSI sequences and computes a style per
// rune of the resulting text. Non-CSI escape bytes are dropped as
// control characters (their following bytes remain as text).
func parseANSIDisplay(s string) (string, []styleDef) {
	var out []rune
	var styles []styleDef
	cur := styleDef{}
	i := 0
	for i < len(s) {
