	underline bool
	reverse   bool
	bgBold    bool
}

func (s styleDef) isPlain() bool {
	return !s.hasFg && !s.hasBg && !s.bold && !s.underline && !s.reverse && !s.bgBold
}

// toTcell converts to a tcell style.
func (s styleDef) toTcell() tcell.Style {
	st := tcell.StyleDefault
	if s.hasFg {
		st = st.Foreground(s.fg)
	}
	if s.hasBg {
		st = st.Background(s.bg)
	}
	st = st.Bold(s.bold || s.bgBold)
	st = st.Underline(s.underline)
	st = st.Reverse(s.reverse)
	return st
}

// withMatchedForeground returns the style obtained by keeping the
// background of s and replacing its foreground side with m's.
func (s styleDef) withMatchedForeground(m styleDef) styleDef {
	out := s
	out.hasFg = m.hasFg
	out.fg = m.fg
	out.bold = m.bold
	out.underline = m.underline
	out.reverse = m.reverse
	// bgBold belongs to the background side and is preserved.
	return out
}

func ansiBaseColor(i int) tcell.Color {
	switch i {
	case 0:
		return tcell.ColorBlack
	case 1:
		return tcell.ColorMaroon
	case 2:
		return tcell.ColorGreen
	case 3:
		return tcell.ColorOlive
	case 4:
		return tcell.ColorNavy
	case 5:
		return tcell.ColorPurple
	case 6:
		return tcell.ColorTeal
	default:
		return tcell.ColorSilver
	}
}

func paletteColor(n int) tcell.Color {
	if n < 0 {
		n = 0
	}
	if n > 255 {
		n = 255
	}
	return tcell.PaletteColor(n)
}

func rgbColor(r, g, b int) tcell.Color {
	return tcell.NewRGBColor(int32(clamp255(r)), int32(clamp255(g)), int32(clamp255(b)))
}

func clamp255(v int) int {
	if v < 0 {
		return 0
	}
	if v > 255 {
		return 255
	}
	return v
}

var namedColors = map[string]tcell.Color{
	"black":   tcell.ColorBlack,
	"red":     tcell.ColorMaroon,
	"green":   tcell.ColorGreen,
	"yellow":  tcell.ColorOlive,
	"blue":    tcell.ColorNavy,
	"magenta": tcell.ColorPurple,
	"cyan":    tcell.ColorTeal,
	"white":   tcell.ColorSilver,
}

