		case "bold":
			st.bold = true
		case "underline":
			st.underline = true
		case "reverse":
			st.reverse = true
		default:
			if c, ok := parseStyleColor(tok); ok {
				st.hasFg = true
				st.fg = c
			}
		}
	}
	return st
}

// styleSet holds the effective styles used for drawing.
type styleSet struct {
	basic          styleDef
	savedSelection styleDef
	selected       styleDef
	query          styleDef
	queryCursor    styleDef
	matched        styleDef
	prompt         styleDef
	context        styleDef
}

