		st = st.Background(s.bg)
	}
	st = st.Bold(s.bold || s.bgBold)
	st = st.Underline(s.underline)
	st = st.Reverse(s.reverse)
	return st
}

// withMatchedForeground returns the style obtained by keeping the
// background of s and replacing its foreground side with m's.
func (s styleDef) withMatchedForeground(m styleDef) styleDef {
	out := s
	out.hasFg = m.hasFg
	out.fg = m.fg
	out.bold = m.bold
	out.underline = m.underline
	out.reverse = m.reverse
	// bgBold belongs to the background side and is preserved.
	return out
}

func ansiBaseColor(i int) tcell.Color {
	switch i {
	case 0:
		return tcell.ColorBlack
	case 1:
		return tcell.ColorMaroon
	case 2:
		return tcell.ColorGreen
	case 3:
		return tcell.ColorOlive
	case 4:
		return tcell.ColorNavy
	case 5:
		return tcell.ColorPurple
	case 6:
		return tcell.ColorTeal
	default:
		return tcell.ColorSilver
	}
}

func paletteColor(n int) tcell.Color {
	if n < 0 {
		n = 0
	}
	if n > 255 {
		n = 255
	}
	return tcell.PaletteColor(n)
}

func rgbColor(r, g, b int) tcell.Color {
	return tcell.NewRGBColor(int32(clamp255(r)), int32(clamp255(g)), int32(clamp255(b)))
}

func clamp255(v int) int {
	if v < 0 {
		return 0
	}
	if v > 255 {
		return 255
	}
	return v
}

var namedColors = map[string]tcell.Color{
	"black":   tcell.ColorBlack,
	"red":     tcell.ColorMaroon,
	"green":   tcell.ColorGreen,
	"yellow":  tcell.ColorOlive,
	"blue":    tcell.ColorNavy,
	"magenta": tcell.ColorPurple,
	"cyan":    tcell.ColorTeal,
	"white":   tcell.ColorSilver,
}

// parseStyleColor parses a colour token (without any on_ prefix).
func parseStyleColor(tok string) (tcell.Color, bool) {
	if tok == "default" {
		return tcell.ColorDefault, true
	}
	if c, ok := namedColors[tok]; ok {
		return c, true
	}
	if strings.HasPrefix(tok, "#") {
		h := tok[1:]
		if len(h) == 6 {
			if v, err := strconv.ParseInt(h, 16, 32); err == nil {
				return tcell.NewHexColor(int32(v)), true
			}
		}
		return tcell.ColorDefault, false
	}
	// Numeric colours 0-255.
	if isAllDigits(tok) {
		if n, err := strconv.Atoi(tok); err == nil && n >= 0 && n <= 255 {
			return tcell.PaletteColor(n), true
		}
	}
	return tcell.ColorDefault, false
}

func isAllDigits(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

// parseStyleTokens builds a styleDef from a list of style tokens.
// Unknown tokens are ignored.
func parseStyleTokens(tokens []string) styleDef {
	var st styleDef
	for _, tok := range tokens {
		if strings.HasPrefix(tok, "on_") {
			rest := tok[3:]
			if rest == "bold" {
				st.bgBold = true
				continue
			}
			if c, ok := parseStyleColor(rest); ok {
				st.hasBg = true
				st.bg = c
			}
			continue
		}
		switch tok {
		case "bold":
			st.bold = true
		case "underline":
			st.underline = true
		case "reverse":
			st.reverse = true
		default:
			if c, ok := parseStyleColor(tok); ok {
				st.hasFg = true
				st.fg = c
			}
		}
	}
	return st
}

// styleSet holds the effective styles used for drawing.
type styleSet struct {
	basic          styleDef
	savedSelection styleDef
	selected       styleDef
	query          styleDef
	queryCursor    styleDef
	matched        styleDef
	prompt         styleDef
	context        styleDef
}

func defaultStyleSet() styleSet {
	return styleSet{
		basic:          styleDef{},
		savedSelection: styleDef{hasFg: true, fg: tcell.ColorBlack, hasBg: true, bg: tcell.ColorTeal, bold: true},
		selected:       styleDef{hasBg: true, bg: tcell.ColorPurple, underline: true},
		query:          styleDef{},
		queryCursor:    styleDef{},
		matched:        styleDef{hasFg: true, fg: tcell.ColorTeal},
		prompt:         styleDef{},
		context:        styleDef{bold: true},
	}
}

// applyConfig applies raw style definitions (name -> tokens) onto a
// default set.
func (ss *styleSet) applyConfig(defs map[string][]string) {
	for name, tokens := range defs {
		st := parseStyleTokens(tokens)
		switch name {
		case "Basic":
			ss.basic = st
		case "SavedSelection":
			ss.savedSelection = st
		case "Selected":
			ss.selected = st
		case "Query":
			ss.query = st
		case "QueryCursor":
			ss.queryCursor = st
		case "Matched":
			ss.matched = st
		case "Prompt":
			ss.prompt = st
		case "Context":
			ss.context = st
		}
	}
}
