	}

	// Substring filters.
	caseSensitive := false
	switch name {
	case "CaseSensitive", "Regexp":
		caseSensitive = true
	case "SmartCase":
		for _, t := range terms {
			if anyUpper(t.text) {
				caseSensitive = true
				break
			}
		}
	}
	var pos, neg [][]rune
	for _, t := range terms {
		if t.negative {
			neg = append(neg, []rune(t.text))
		} else {
			pos = append(pos, []rune(t.text))
		}
	}
	var lines []*Line
	for _, line := range base {
		ok := true
		for _, n := range neg {
			if substringContains(line.displayRunes, n, caseSensitive) {
				ok = false
				break
			}
		}
		if !ok {
			continue
		}
		var ranges [][2]int
		for _, p := range pos {
			r := substringMatches(line.displayRunes, p, caseSensitive)
			if len(r) == 0 && len(p) > 0 {
				ok = false
				break
			}
			ranges = append(ranges, r...)
		}
		if !ok {
			continue
		}
		lines = append(lines, line)
		markMatches(matched, line, ranges)
	}
	return filterResult{lines: lines, matched: matched}
}

func hasNegative(terms []queryTerm) bool {
	for _, t := range terms {
		if t.negative {
			return true
		}
	}
	return false
}

func runRegexpFilter(insensitive bool, terms []queryTerm, base []*Line) filterResult {
	matched := make(map[int][]bool)
	compile := func(text string) (*regexp.Regexp, error) {
		if insensitive {
			return regexp.Compile("(?i)" + text)
		}
		return regexp.Compile(text)
	}
	var pos, neg []*regexp.Regexp
	valid := true
	for _, t := range terms {
		re, err := compile(t.text)
		if err != nil {
			valid = false
			break
		}
		if t.negative {
			neg = append(neg, re)
		} else {
			pos = append(pos, re)
		}
	}
	if !valid {
		return filterResult{lines: nil, matched: matched}
	}
	var lines []*Line
	for _, line := range base {
		ok := true
		for _, re := range neg {
			if re.MatchString(line.display) {
				ok = false
				break
			}
		}
		if !ok {
			continue
		}
		var ranges [][2]int
		for _, re := range pos {
			idxs := re.FindAllStringIndex(line.display, -1)
			if len(idxs) == 0 {
				ok = false
				break
			}
			for _, pair := range idxs {
				if pair[1] > pair[0] {
					rs, re2 := line.byteRangeToRuneRange(pair[0], pair[1])
					if re2 > rs {
						ranges = append(ranges, [2]int{rs, re2})
					}
				}
			}
			// A pattern that only matches the empty string still
			// counts as a match for filtering purposes.
		}
		if !ok {
			continue
		}
		lines = append(lines, line)
		markMatches(matched, line, ranges)
	}
	return filterResult{lines: lines, matched: matched}
}

// -------- fuzzy --------

func fuzzyGreedy(query, target []rune, caseSensitive bool) ([]int, bool) {
	q := query
	t := target
	if !caseSensitive {
		q = loweredRunes(query)
		t = loweredRunes(target)
	}
	var idxs []int
	ti := 0
	for qi := 0; qi < len(q); qi++ {
		found := false
		for ; ti < len(t); ti++ {
			if t[ti] == q[qi] {
				idxs = append(idxs, ti)
				ti++
				found = true
				break
			}
		}
		if !found {
			return nil, false
		}
	}
	return idxs, true
}

func fuzzyCaseSensitive(terms []queryTerm) bool {
	for _, t := range terms {
		if !t.negative && anyUpper(t.text) {
			return true
		}
	}
	return false
}

func runFuzzyFilter(terms []queryTerm, base []*Line, longestSort bool) filterResult {
	matched := make(map[int][]bool)
	caseSensitive := fuzzyCaseSensitive(terms)
	// The positive terms are matched sequentially, i.e. as their
	// concatenation.
	var posRunes []rune
	for _, t := range terms {
		if !t.negative {
			posRunes = append(posRunes, []rune(t.text)...)
		}
	}
	type scored struct {
		line       *Line
		lcsLen     int
		lcsPos     int
		idxs       []int
	}
	var scoredLines []scored
	var lines []*Line
	for _, line := range base {
		excluded := false
		for _, t := range terms {
			if !t.negative {
				continue
			}
			if substringContains(line.displayRunes, []rune(t.text), false) {
				excluded = true
				break
			}
		}
		if excluded {
			continue
		}
		if len(posRunes) == 0 {
			lines = append(lines, line)
			continue
		}
		if longestSort {
			idxs, lcsLen, lcsPos, ok := fuzzyLongestMatch(posRunes, line.displayRunes, caseSensitive)
			if !ok {
				continue
			}
			scoredLines = append(scoredLines, scored{line: line, lcsLen: lcsLen, lcsPos: lcsPos, idxs: idxs})
			markIndices(matched, line, idxs)
			continue
		}
		idxs, ok := fuzzyGreedy(posRunes, line.displayRunes, caseSensitive)
		if !ok {
			continue
		}
		lines = append(lines, line)
		markIndices(matched, line, idxs)
	}
	if longestSort {
		sort.SliceStable(scoredLines, func(i, j int) bool {
			if scoredLines[i].lcsLen != scoredLines[j].lcsLen {
				return scoredLines[i].lcsLen > scoredLines[j].lcsLen
			}
			if scoredLines[i].lcsPos != scoredLines[j].lcsPos {
				return scoredLines[i].lcsPos < scoredLines[j].lcsPos
			}
			return len(scoredLines[i].line.displayRunes) < len(scoredLines[j].line.displayRunes)
		})
		for _, s := range scoredLines {
			lines = append(lines, s.line)
		}
	}
	return filterResult{lines: lines, matched: matched}
}

// fuzzyLongestMatch finds an alignment of query as a subsequence of
// target that maximises the longest contiguous matching block.
func fuzzyLongestMatch(query, target []rune, caseSensitive bool) ([]int, int, int, bool) {
	if len(query) == 0 {
		return nil, 0, 0, true
	}
	// Avoid quadratic blow-ups on huge inputs.
	if len(query)*len(target) > 4_000_000 {
		idxs, ok := fuzzyGreedy(query, target, caseSensitive)
		if !ok {
			return nil, 0, 0, false
		}
		return idxs, 1, firstIndex(idxs), true
	}
	q, t := query, target
	if !caseSensitive {
		q = loweredRunes(query)
		t = loweredRunes(target)
	}
	lcsLen, candidates := longestCommonSubstringCandidates(q, t)
	if lcsLen == 0 {
		return nil, 0, 0, false
	}
	for _, cand := range candidates {
		qStart, tStart := cand[0], cand[1]
		prefixIdxs, _, _, ok1 := fuzzyLongestMatchRec(query[:qStart], target[:tStart], caseSensitive)
		if !ok1 {
			continue
		}
		suffixIdxs, _, _, ok2 := fuzzyLongestMatchRec(query[qStart+lcsLen:], target[tStart+lcsLen:], caseSensitive)
		if !ok2 {
			continue
		}
		var idxs []int
		idxs = append(idxs, prefixIdxs...)
		for i := 0; i < lcsLen; i++ {
			idxs = append(idxs, tStart+i)
		}
		for _, si := range suffixIdxs {
			idxs = append(idxs, tStart+lcsLen+si)
		}
		return idxs, lcsLen, tStart, true
	}
	return nil, 0, 0, false
}

// fuzzyLongestMatchRec matches the prefix/suffix fragments. An empty
// query trivially matches; otherwise it defers to fuzzyLongestMatch but
// treats a zero-length LCS as failure. It is kept separate so the
// top-level candidate logic stays simple.
func fuzzyLongestMatchRec(query, target []rune, caseSensitive bool) ([]int, int, int, bool) {
	if len(query) == 0 {
		return nil, 0, 0, true
	}
	return fuzzyLongestMatch(query, target, caseSensitive)
}

func firstIndex(idxs []int) int {
	if len(idxs) == 0 {
		return 0
	}
	return idxs[0]
}

// longestCommonSubstringCandidates returns the maximum length and all
// (queryStart, targetStart) pairs achieving it, ordered by target start
// then query start.
func longestCommonSubstringCandidates(q, t []rune) (int, [][2]int) {
	if len(q) == 0 || len(t) == 0 {
		return 0, nil
	}
	// DP over t for each q row.
	prev := make([]int, len(t)+1)
	cur := make([]int, len(t)+1)
	best := 0
	for i := 1; i <= len(q); i++ {
		for j := 1; j <= len(t); j++ {
			if q[i-1] == t[j-1] {
				cur[j] = prev[j-1] + 1
				if cur[j] > best {
					best = cur[j]
				}
			} else {
				cur[j] = 0
			}
		}
		copy(prev, cur)
	}
	if best == 0 {
		return 0, nil
	}
	var cands [][2]int
	seen := make(map[[2]int]bool)
	// Enumerate occurrences: scan target starts in order.
	for ts := 0; ts+best <= len(t); ts++ {
		for qs := 0; qs+best <= len(q); qs++ {
			if runesEqual(t[ts:ts+best], q[qs:qs+best]) {
				c := [2]int{qs, ts}
				if !seen[c] {
					seen[c] = true
					cands = append(cands, c)
				}
			}
		}
	}
	// Sort by target start then query start.
	sort.Slice(cands, func(i, j int) bool {
		if cands[i][1] != cands[j][1] {
			return cands[i][1] < cands[j][1]
		}
		return cands[i][0] < cands[j][0]
	})
	return best, cands
}

// -------- external custom filters --------

type customFilterDef struct {
	name            string
	cmd             string
	args            []string
	bufferThreshold int
}

func (cf *customFilterDef) threshold() int {
	if cf.bufferThreshold <= 0 {
		return 100
	}
	return cf.bufferThreshold
}

func (cf *customFilterDef) argList(query string) []string {
	args := cf.args
	if len(args) == 0 {
		args = []string{"$QUERY"}
	}
	out := make([]string, len(args))
	for i, a := range args {
		if a == "$QUERY" {
			out[i] = query
		} else {
			out[i] = a
		}
	}
	return out
}

// runCustomFilter runs the external command in batches over base.
func runCustomFilter(cf *customFilterDef, query string, base []*Line, nullSep bool, ansi bool) filterResult {
	matched := make(map[int][]bool)
	var lines []*Line
	if len(base) == 0 {
		return filterResult{lines: lines, matched: matched}
	}
	th := cf.threshold()
	for start := 0; start < len(base); start += th {
		end := start + th
		if end > len(base) {
			end = len(base)
		}
		batch := base[start:end]
		var input bytes.Buffer
		for _, l := range batch {
			input.WriteString(l.raw)
			input.WriteByte('\n')
		}
		cmd := exec.Command(cf.cmd, cf.argList(query)...)
		cmd.Stdin = bytes.NewReader(input.Bytes())
		var stdout bytes.Buffer
		cmd.Stdout = &stdout
		_ = cmd.Run()
		// The output is read in 4096-byte line fragments.
		reader := bufio.NewReaderSize(&stdout, 4096)
		for {
			frag, isPrefix, err := reader.ReadLine()
			if err != nil {
				break
			}
			_ = isPrefix
			lines = append(lines, newLine(string(frag), nullSep, ansi))
		}
	}
	return filterResult{lines: lines, matched: matched}
}
