package main

import (
	"fmt"
	"strconv"
	"strings"

	"github.com/gdamore/tcell/v2"
)

// Modifiers for a key.
const (
	modCtrl uint8 = 1 << iota
	modShift
	modAlt
)

type keyKind int

const (
	keyRuneKind keyKind = iota
	keySpecialKind
	keyControlKind
)

// keyVal identifies a single key press.
type keyVal struct {
	kind    keyKind
	r       rune   // for keyRuneKind
	special string // canonical special id for keySpecialKind (e.g. ArrowDown, Pgdn, F1, MouseLeft, BS2)
	ctrl    rune   // for keyControlKind: the base character ('a', ' ', '\\', ...)
	mods    uint8  // extra modifiers; for special keys this includes Ctrl/Shift/Alt
}

func runeKey(r rune) keyVal { return keyVal{kind: keyRuneKind, r: r} }

func (k keyVal) String() string {
	switch k.kind {
	case keyRuneKind:
		if k.mods == 0 {
			if k.r == ' ' {
				return "Space"
			}
			return string(k.r)
		}
		return modPrefix(k.mods) + string(k.r)
	case keyControlKind:
		base := "C-" + ctrlName(k.ctrl)
		if k.mods == 0 {
			return base
		}
		// Extra modifiers precede the whole C-x name (e.g. M-C-a).
		return extraModPrefix(k.mods) + base
	default: // special
		return modPrefix(k.mods) + specialDisplayName(k.special)
	}
}

func ctrlName(r rune) string {
	if r == ' ' {
		return "Space"
	}
	if r >= 'a' && r <= 'z' {
		return string(r)
	}
	return string(r)
}

// modPrefix renders modifiers in C-, S-, M- order.
func modPrefix(m uint8) string {
	var b strings.Builder
	if m&modCtrl != 0 {
		b.WriteString("C-")
	}
	if m&modShift != 0 {
		b.WriteString("S-")
	}
	if m&modAlt != 0 {
		b.WriteString("M-")
	}
	return b.String()
}

// extraModPrefix is used for modifiers carried alongside a control key
// (where Ctrl is already part of the base name).
func extraModPrefix(m uint8) string {
	var b strings.Builder
	if m&modAlt != 0 {
		b.WriteString("M-")
	}
	if m&modShift != 0 {
		b.WriteString("S-")
	}
	if m&modCtrl != 0 {
		b.WriteString("C-")
	}
	return b.String()
}

var specialDisplayNames = map[string]string{
	"ArrowUp":    "^",
	"ArrowDown":  "v",
	"ArrowLeft":  "<",
	"ArrowRight": ">",
	"Pgup":       "Pgup",
	"Pgdn":       "Pgdn",
	"Home":       "Home",
	"End":        "End",
	"Insert":     "Insert",
	"Delete":     "Delete",
	"BS":         "BS",
	"BS2":        "BS2",
	"Tab":        "Tab",
	"Enter":      "Enter",
	"Esc":        "Esc",
	"MouseLeft":   "MouseLeft",
	"MouseMiddle": "MouseMiddle",
	"MouseRight":  "MouseRight",
}

func specialDisplayName(id string) string {
	if s, ok := specialDisplayNames[id]; ok {
		return s
	}
	return id // F1..F64 etc.
}

var specialNames = map[string]bool{
	"ArrowUp": true, "ArrowDown": true, "ArrowLeft": true, "ArrowRight": true,
	"Pgup": true, "Pgdn": true, "Home": true, "End": true,
	"Insert": true, "Delete": true, "BS": true, "BS2": true,
	"Tab": true, "Enter": true, "Return": true, "Esc": true,
	"MouseLeft": true, "MouseMiddle": true, "MouseRight": true,
}

// parseSingleKey converts one comma-separated key component.
func parseSingleKey(component string) (keyVal, error) {
	s := strings.TrimSpace(component)
	if s == "" {
		return keyVal{}, fmt.Errorf("failed to convert '%s': no such key", s)
	}
	orig := s
	var mods uint8
	// Strip modifier prefixes in any order.
	for {
		if strings.HasPrefix(s, "C-") {
			mods |= modCtrl
			s = s[2:]
		} else if strings.HasPrefix(s, "M-") {
			mods |= modAlt
			s = s[2:]
		} else if strings.HasPrefix(s, "S-") {
			mods |= modShift
			s = s[2:]
		} else {
			break
		}
	}
	if s == "" {
		return keyVal{}, fmt.Errorf("failed to convert '%s': no such key", orig)
	}
	// Special names (Return is a synonym for Enter).
	if specialNames[s] {
		id := s
		if id == "Return" {
			id = "Enter"
		}
		if mods&modCtrl != 0 && mods&(modAlt|modShift) == 0 && len(s) == 0 {
			// unreachable; kept for clarity
		}
		return keyVal{kind: keySpecialKind, special: id, mods: mods}, nil
	}
	if s == "C-Space" && false {
		// handled below as a single component name
	}
	if s == "Space" && mods == 0 {
		return runeKey(' '), nil
	}
	runes := []rune(s)
	if mods == 0 {
		// Unknown names fall back to their first rune.
		return runeKey(runes[0]), nil
	}
	// With modifiers: a canonical name is handled above. Otherwise the
	// key is built from the first rune of the remainder.
	if mods&modCtrl != 0 && len(runes) == 1 && (mods&(modAlt|modShift)) == 0 {
		// Plain Ctrl+<char>.
		return controlKeyFromRune(runes[0]), nil
	}
	if mods&modCtrl != 0 && len(runes) == 1 && mods == modCtrl {
		return controlKeyFromRune(runes[0]), nil
	}
	k := keyVal{kind: keyRuneKind, r: runes[0], mods: mods}
	// Ctrl combined with a single rune in the presence of other
	// modifiers: represent as a modified rune (which no ordinary
	// terminal event will produce as a control key).
	return k, nil
}

// controlKeyFromRune builds the key for Ctrl+<rune>.
func controlKeyFromRune(r rune) keyVal {
	if r >= 'A' && r <= 'Z' {
		r = r - 'A' + 'a'
	}
	return keyVal{kind: keyControlKind, ctrl: r}
}

// parseKeySequence parses a full "A,B,C" key sequence specification.
func parseKeySequence(spec string) ([]keyVal, error) {
	parts := strings.Split(spec, ",")
	var out []keyVal
	for _, part := range parts {
		k, err := parseSingleKey(part)
		if err != nil {
			return nil, err
		}
		out = append(out, k)
	}
	return out, nil
}

// seqKey encodes a key sequence for map lookup.
func seqKey(seq []keyVal) string {
	var b strings.Builder
	for _, k := range seq {
		b.WriteString(k.encode())
		b.WriteByte(0)
	}
	return b.String()
}

func (k keyVal) encode() string {
	return fmt.Sprintf("%d|%d|%s|%d", int(k.kind), k.r, k.special, k.mods*256+int(k.ctrl))
}

