// keyFromEvent converts a tcell key event into our key representation.
// It returns false when the event should be ignored entirely (NUL).
func keyFromEvent(ev *tcell.EventKey) (keyVal, bool) {
	key := ev.Key()
	mods := ev.Modifiers()
	var extra uint8
	if mods&tcell.ModAlt != 0 {
		extra |= modAlt
	}
	if mods&tcell.ModShift != 0 {
		extra |= modShift
