// controlKeyFromRune builds the key for Ctrl+<rune>.
func controlKeyFromRune(r rune) keyVal {
	if r >= 'A' && r <= 'Z' {
		r = r - 'A' + 'a'
	}
	return keyVal{kind: keyControlKind, ctrl: r}
