// parseKeySequence parses a full "A,B,C" key sequence specification.
func parseKeySequence(spec string) ([]keyVal, error) {
	parts := strings.Split(spec, ",")
	var out []keyVal
	for _, part := range parts {
		k, err := parseSingleKey(part)
		if err != nil {
			return nil, err
		}
		out = append(out, k)
	}
	return out, nil
