		return keyVal{kind: keySpecialKind, special: "Home", mods: extra}, true
	case tcell.KeyEnd:
		return keyVal{kind: keySpecialKind, special: "End", mods: extra}, true
	case tcell.KeyInsert:
		return keyVal{kind: keySpecialKind, special: "Insert", mods: extra}, true
