func controlKeyFromTcell(key tcell.Key, extra uint8) (keyVal, bool) {
	// Modifiers other than the implicit control itself, for use when a
	// control key arrives with e.g. Alt.
	extraNoCtrl := extra &^ modCtrl
	kv := int(key)
	// tcell control key constants (KeyCtrlSpace == 64 onwards).
	if kv >= int(tcell.KeyCtrlSpace) && kv <= int(tcell.KeyCtrlUnderscore) {
		idx := kv - int(tcell.KeyCtrlSpace)
		var r rune
		if idx == 0 {
			r = ' '
		} else if idx >= 1 && idx <= 26 {
			r = rune('a' + idx - 1)
		} else {
			r = []rune{'[', '\\', ']', '~', '_'}[idx-27]
		}
		// Tab/Enter/Esc/BS specials.
		switch r {
		case 'i':
			return keyVal{kind: keySpecialKind, special: "Tab", mods: extraNoCtrl}, true
		case 'm':
			return keyVal{kind: keySpecialKind, special: "Enter", mods: extraNoCtrl}, true
		case 'h':
			return keyVal{kind: keySpecialKind, special: "BS", mods: extraNoCtrl}, true
		case '[':
			// Ctrl-[ is Esc unless other modifiers are present.
			if extraNoCtrl == 0 {
				return keyVal{kind: keySpecialKind, special: "Esc"}, true
			}
		}
		return keyVal{kind: keyControlKind, ctrl: r, mods: extraNoCtrl}, true
	}
	// Raw ASCII control codes.
	switch {
	case kv == 0:
		// NUL is ignored entirely.
		return keyVal{}, false
	case kv == 27:
		return keyVal{kind: keySpecialKind, special: "Esc", mods: extraNoCtrl}, true
	case kv == 9:
		return keyVal{kind: keySpecialKind, special: "Tab", mods: extraNoCtrl}, true
	case kv == 13:
		return keyVal{kind: keySpecialKind, special: "Enter", mods: extraNoCtrl}, true
	case kv == 8 || kv == 127:
		return keyVal{kind: keySpecialKind, special: "BS", mods: extraNoCtrl}, true
	case kv >= 1 && kv <= 26:
		r := rune('a' + kv - 1)
		return keyVal{kind: keyControlKind, ctrl: r, mods: extraNoCtrl}, true
	case kv >= 28 && kv <= 31:
		r := []rune{'\\', ']', '~', '_'}[kv-28]
		return keyVal{kind: keyControlKind, ctrl: r, mods: extraNoCtrl}, true
	}
	return keyVal{}, false
}

// mouseKeyFromEvent converts a mouse press into a key, if applicable.
func mouseKeyFromEvent(ev *tcell.EventMouse) (keyVal, bool) {
	btn := ev.Buttons()
	switch {
	case btn&tcell.Button1 != 0:
		return keyVal{kind: keySpecialKind, special: "MouseLeft"}, true
	case btn&tcell.Button2 != 0:
		return keyVal{kind: keySpecialKind, special: "MouseMiddle"}, true
	case btn&tcell.Button3 != 0:
		return keyVal{kind: keySpecialKind, special: "MouseRight"}, true
	}
	return keyVal{}, false
}
