		{long: "prompt", display: "--prompt", set: str(func(o *options, v string) { o.prompt = v })},
		{long: "layout", display: "--layout", set: str(func(o *options, v string) { o.layout = v })},
		{long: "select-1", isBool: true, display: "--select-1", setBool: func(o *options) { o.select1 = true }},
		{long: "exit-0", isBool: true, display: "--exit-0", setBool: func(o *options) { o.exit0 = true }},
		{long: "select-all", isBool: true, display: "--select-all", setBool: func(o *options) { o.selectAll = true }},
		{long: "on-cancel", display: "--on-cancel", set: str(func(o *options, v string) { o.onCancel = v })},
		{long: "selection-prefix", display: "--selection-prefix", set: str(func(o *options, v string) { o.selectionPrefix = v })},
		{long: "exec", display: "--exec", set: str(func(o *options, v string) { o.exec = v })},
		{long: "print-query", isBool: true, display: "--print-query", setBool: func(o *options) { o.printQuery = true }},
		{long: "ansi", isBool: true, display: "--ansi", setBool: func(o *options) { o.ansi = true }},
		{long: "height", display: "--height", set: str(func(o *options, v string) { o.height = v })},
	}
}

// cliError is a syntactic flag parsing error. The message has already
// been (or will be) printed together with the usage text.
type cliError struct{ msg string }

func (e *cliError) Error() string { return e.msg }

func isOptionToken(tok string) bool {
	if tok == "-" || tok == "--" || strings.HasPrefix(tok, "---") {
		return false
	}
	if len(tok) >= 2 && tok[0] == '-' {
		return true
	}
	return false
}

func isNegativeIntToken(tok string) bool {
	if len(tok) < 2 || tok[0] != '-' {
		return false
	}
	for i := 1; i < len(tok); i++ {
		if tok[i] < '0' || tok[i] > '9' {
			return false
		}
	}
	return true
}

// parseCommandLine parses os.Args-style arguments. On a syntactic error
// it writes the error and usage text to errOut and returns a cliError.
func parseCommandLine(args []string, errOut io.Writer) (*options, error) {
	defs := flagDefs()
	byLong := make(map[string]*flagDef)
	byShort := make(map[byte]*flagDef)
	for _, d := range defs {
		byLong[d.long] = d
		if d.short != 0 {
			byShort[d.short] = d
		}
	}
	o := &options{}
	fail := func(msg string) (*options, error) {
		fmt.Fprintln(errOut, msg)
		fmt.Fprint(errOut, helpText)
		return nil, &cliError{msg: msg}
	}
	setValue := func(d *flagDef, v string) (string, bool) {
		if err := d.set(o, v); err != nil {
			if d.isInt {
				return fmt.Sprintf("invalid argument for flag `%s' (expected int): %s", d.display, err.Error()), false
			}
			return fmt.Sprintf("invalid argument for flag `%s': %s", d.display, err.Error()), false
		}
		return "", true
	}
	// nextValue obtains a separate-token value for a flag.
	nextValue := func(d *flagDef, i *int) (string, *options, error) {
		if *i+1 >= len(args) {
			oo, err := fail(fmt.Sprintf("expected argument for flag `%s'", d.display))
			return "", oo, err
		}
		next := args[*i+1]
		if isOptionToken(next) && !(d.isInt && isNegativeIntToken(next)) {
			oo, err := fail(fmt.Sprintf("expected argument for flag `%s', but got option `%s'", d.display, next))
			return "", oo, err
		}
		*i++
		return next, nil, nil
	}

	for i := 0; i < len(args); i++ {
		tok := args[i]
		if strings.HasPrefix(tok, "--") && !strings.HasPrefix(tok, "---") {
			body := tok[2:]
			name := body
			var attached *string
			if idx := strings.IndexByte(body, '='); idx >= 0 {
				name = body[:idx]
				v := body[idx+1:]
				attached = &v
			}
			d, ok := byLong[name]
			if !ok {
				return fail(fmt.Sprintf("unknown flag `%s'", name))
			}
			if d.isBool {
				if attached != nil {
					return fail(fmt.Sprintf("bool flag `%s' cannot have an argument", d.display))
				}
				d.setBool(o)
				continue
			}
			var v string
			if attached != nil {
				v = *attached
			} else {
				val, oo, err := nextValue(d, &i)
				if err != nil {
					return oo, err
				}
				v = val
			}
			if msg, ok2 := setValue(d, v); !ok2 {
				return fail(msg)
			}
			continue
		}
		if len(tok) >= 2 && tok[0] == '-' && tok != "-" && !strings.HasPrefix(tok, "---") {
			// Short flag cluster.
			rest := tok[1:]
			consumed := false
			for pos := 0; pos < len(rest); pos++ {
				ch := rest[pos]
				d, ok := byShort[ch]
				if !ok {
					return fail(fmt.Sprintf("unknown flag `%c'", ch))
				}
				if d.isBool {
					if pos+1 < len(rest) && rest[pos+1] == '=' {
						return fail(fmt.Sprintf("bool flag `%s' cannot have an argument", d.display))
					}
					d.setBool(o)
					continue
				}
				// Non-bool short flag takes the rest as its value.
				var v string
				remainder := rest[pos+1:]
				if remainder != "" {
					if strings.HasPrefix(remainder, "=") {
						v = remainder[1:]
					} else {
						v = remainder
					}
				} else {
					val, oo, err := nextValue(d, &i)
					if err != nil {
						return oo, err
					}
					v = val
				}
				if msg, ok2 := setValue(d, v); !ok2 {
					return fail(msg)
				}
				consumed = true
				break
			}
			_ = consumed
			continue
		}
		// Positional argument.
		o.args = append(o.args, tok)
	}
	// Argument validation performed at parse time.
	switch o.layout {
	case "", "top-down", "bottom-up", "top-down-query-bottom":
	default:
		return nil, fmt.Errorf("invalid command line arguments: unknown layout: '%s'", o.layout)
	}
	return o, nil
}
EOF
gofmt -w cli.go"}

