{"command":"cat > peco.go <<'EOF'
package main

import (
	"fmt"
	"os"
	"os/exec"
	"sort"
	"strings"
	"sync"
	"time"

	"github.com/gdamore/tcell/v2"
	"peco/config"
)

// ---------- height ----------

type heightSpec struct {
	isPercent bool
	value     int
}

func parseHeight(spec string) (*heightSpec, error) {
	s := strings.TrimSpace(spec)
	if s == "" {
		return nil, fmt.Errorf("empty height specification")
	}
	if strings.HasSuffix(s, "%") {
		v, err := atoiStrict(strings.TrimSuffix(s, "%"))
		if err != nil {
			return nil, fmt.Errorf("invalid height specification: %q", s)
		}
		if v <= 0 {
			return nil, fmt.Errorf("height percentage must be positive: %q", s)
		}
		if v > 100 {
			return nil, fmt.Errorf("height percentage must not exceed 100: %q", s)
		}
		return &heightSpec{isPercent: true, value: v}, nil
	}
	v, err := atoiStrict(s)
	if err != nil {
		return nil, fmt.Errorf("invalid height specification: %q", s)
	}
	if v <= 0 {
		return nil, fmt.Errorf("height must be positive: %q", s)
	}
	return &heightSpec{value: v}, nil
}

func atoiStrict(s string) (int, error) {
	// Matches strconv.Atoi behaviour.
	return stringsAtoi(s)
}

// ---------- filters registry ----------

type filterEntry struct {
	name   string
	custom *customFilterDef // nil for built-ins
}

// ---------- input store ----------

type inputStore struct {
	mu    sync.Mutex
	lines []*Line
	done  bool
}

func (s *inputStore) snapshot() []*Line {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := make([]*Line, len(s.lines))
	copy(out, s.lines)
	return out
}

func (s *inputStore) count() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return len(s.lines)
}

func (s *inputStore) isDone() bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.done
}

// ---------- main state ----------

type peco struct {
	opts *options
	cfg  *config.Config

	styles          styleSet
	prompt          string
	layout          string
	onCancel        config.OnCancelBehavior
	filters         []filterEntry
	currentFilter   int
	fuzzyLongest    bool
	sticky          bool
	suppressStatus  bool
	ansiEnabled     bool
	nullSep         bool
	selectionPrefix string
	showJumpPrefix  bool
	height          *heightSpec
	bufferSize      int
	execCmd         string

	screen    tcell.Screen
	inlineTTY *os.File
	inlineTop int

	store *inputStore

	query      []rune
	cursor     int
	savedQuery []rune
	hasSaved   bool

	filtered       []*Line
	matched        map[int][]bool
	display        []*Line
	displayContext map[int]bool
	zoomed         bool
	preZoomIndex   int

	selectedIdx int
	saved       map[int]*Line

	rangeActive   bool
	rangeAnchorID int
	rangeContrib  map[int]*Line

	frozen    []*Line
	hasFrozen bool

	horizOffset int

	statusMsg     string
	keyseqText    string
	keyseqGen     int
	pending       []keyVal
	inSingleJump  bool
	firstRefresh  bool
	inputPostFunc func()
	inputPending  int32
	flashPostFunc func(gen int)

	done         bool
	doneCode     int
	cancelled    bool
	directResult []*Line // selection produced by a shortcut
	returnErr    error
	requestSync  bool
}

func (p *peco) queryString() string { return string(p.query) }

func (p *peco) baseLines() []*Line {
	if p.hasFrozen {
		out := make([]*Line, len(p.frozen))
		copy(out, p.frozen)
		return out
	}
	return p.store.snapshot()
}

func (p *peco) clampSelected() {
	if len(p.display) == 0 {
		p.selectedIdx = 0
		return
	}
	if p.selectedIdx < 0 {
		p.selectedIdx = 0
	}
	if p.selectedIdx >= len(p.display) {
		p.selectedIdx = len(p.display) - 1
	}
}

func (p *peco) pageCapacity() int {
	h := p.virtualHeight()
	c := h - 2
	if c < 0 {
		c = 0
	}
	return c
}

func (p *peco) pageSizeForCalc() int {
	c := p.pageCapacity()
	if c <= 0 {
		return 1
	}
	return c
}

func (p *peco) virtualHeight() int {
	_, h := p.screenSize()
	if p.height == nil {
		return h
	}
	total := p.inlineTotalRows(h)
	return total
}

func (p *peco) screenSize() (int, int) {
	if p.screen == nil {
		return 80, 24
	}
	return p.screen.Size()
}

func (p *peco) inlineTotalRows(termH int) int {
	if p.height == nil {
		return termH
	}
	var total int
	if p.height.isPercent {
		total = termH * p.height.value / 100
	} else {
		total = p.height.value + 2
	}
	if total < 3 {
		total = 3
	}
	if total > termH {
		total = termH
	}
	if total < 0 {
		total = 0
	}
	return total
}

// effectiveSaved returns saved selections plus any in-progress range.
func (p *peco) effectiveSaved() map[int]*Line {
	if len(p.rangeContrib) == 0 {
		return p.saved
	}
	out := make(map[int]*Line, len(p.saved)+len(p.rangeContrib))
	for k, v := range p.saved {
		out[k] = v
	}
	for k, v := range p.rangeContrib {
		out[k] = v
	}
	return out
}

func (p *peco) isSaved(id int) bool {
	if _, ok := p.saved[id]; ok {
		return true
	}
	if p.rangeContrib != nil {
		_, ok := p.rangeContrib[id]
		return ok
	}
	return false
}

// ---------- filter execution ----------

func (p *peco) currentFilterEntry() filterEntry {
	if len(p.filters) == 0 {
		return filterEntry{name: "IgnoreCase"}
	}
	return p.filters[p.currentFilter]
}

func (p *peco) executeFilter() filterResult {
	entry := p.currentFilterEntry()
	base := p.baseLines()
	query := p.queryString()
	if entry.custom != nil {
		if query == "" {
			var lines []*Line
			lines = append(lines, base...)
			return filterResult{lines: lines, matched: make(map[int][]bool)}
		}
		return runCustomFilter(entry.custom, query, base, p.nullSep, p.ansiEnabled)
	}
	terms := parseQueryTerms(query)
	return runBuiltinFilter(entry.name, terms, base, p.fuzzyLongest)
}

// refreshFiltered re-runs the current filter and updates the display.
func (p *peco) refreshFiltered() {
	p.refreshFilteredInternal(false)
}

func (p *peco) refreshFilteredInternal(preserveZoomDisplay bool) {
	var savedDisplay []*Line
	if preserveZoomDisplay && p.zoomed {
		savedDisplay = p.display
	}
	if p.screen != nil {
		p.showTransientStatus("Running query...")
	}
	result := p.executeFilter()
	p.filtered = result.lines
	if p.filtered == nil {
		p.filtered = []*Line{}
	}
	p.matched = result.matched
	if p.matched == nil {
		p.matched = make(map[int][]bool)
	}
	if p.zoomed && !preserveZoomDisplay {
		p.zoomed = false
		p.displayContext = nil
	}
	if preserveZoomDisplay && p.zoomed && savedDisplay != nil {
		p.display = savedDisplay
	} else if !p.zoomed {
		p.display = p.filtered
	}
	// Prune saved selections to the filtered set unless sticky.
	if !p.sticky {
		inFiltered := make(map[int]bool, len(p.filtered))
		for _, l := range p.filtered {
			inFiltered[l.id] = true
		}
		for id := range p.saved {
			if !inFiltered[id] {
				delete(p.saved, id)
			}
		}
	}
	p.clampSelected()
	p.recomputeRange()
}

func (p *peco) showTransientStatus(msg string) {
	if p.suppressStatus {
		return
	}
	old := p.statusMsg
	oldKey := p.keyseqText
	p.statusMsg = msg
	p.keyseqText = ""
	p.draw()
	p.statusMsg = old
	p.keyseqText = oldKey
	p.statusMsg = ""
}

// zoomCancel is called by paths that invalidate a zoomed view.
func (p *peco) cancelZoom() {
	if p.zoomed {
		p.zoomed = false
		p.displayContext = nil
		p.display = p.filtered
	}
}

// recomputeRange refreshes the in-progress range selection after the
// display list changes (without a specific movement).
func (p *peco) recomputeRange() {
	if !p.rangeActive {
		return
	}
	anchorPos := -1
	for i, l := range p.display {
		if l.id == p.rangeAnchorID {
			anchorPos = i
			break
		}
	}
	if anchorPos < 0 || len(p.display) == 0 {
		p.rangeContrib = make(map[int]*Line)
		return
	}
	p.rangeContrib = rangeInterval(p.display, anchorPos, p.selectedIdx)
}

func rangeInterval(display []*Line, a, b int) map[int]*Line {
	out := make(map[int]*Line)
	if a < 0 || b < 0 || len(display) == 0 {
		return out
	}
	lo, hi := a, b
	if lo > hi {
		lo, hi = hi, lo
	}
	for i := lo; i <= hi && i < len(display); i++ {
		out[display[i].id] = display[i]
	}
	return out
}

// afterMovement updates an in-progress range selection following a
// cursor movement. kind is "down", "up" or "other".
func (p *peco) afterMovement(kind string) {
	if !p.rangeActive {
		return
	}
	anchorPos := -1
	for i, l := range p.display {
		if l.id == p.rangeAnchorID {
			anchorPos = i
			break
		}
	}
	if anchorPos < 0 || len(p.display) == 0 {
		p.rangeContrib = make(map[int]*Line)
		return
	}
	cur := p.selectedIdx
	switch kind {
	case "up":
		if cur < anchorPos {
			p.rangeContrib = rangeInterval(p.display, cur, anchorPos)
		} else if cur > anchorPos {
			// Selecting upwards towards the anchor excludes the
			// line landed on.
			p.rangeContrib = rangeInterval(p.display, anchorPos, cur-1)
		} else {
			p.rangeContrib = make(map[int]*Line)
		}
	default:
		p.rangeContrib = rangeInterval(p.display, anchorPos, cur)
	}
}

func (p *peco) commitRange() {
	if !p.rangeActive {
		return
	}
	for id, l := range p.rangeContrib {
		p.saved[id] = l
	}
	p.rangeActive = false
	p.rangeContrib = nil
}

// ---------- query mutation ----------

// setQueryFromEditor applies an editor mutation; reruns the filter only
// when the text actually changed.
func (p *peco) applyQueryEdit(newQuery []rune, newCursor int) {
	old := p.queryString()
	p.query = newQuery
	if newCursor < 0 {
		newCursor = 0
	}
	if newCursor > len(newQuery) {
		newCursor = len(newQuery)
	}
	p.cursor = newCursor
	if string(newQuery) != old {
		p.hasSaved = false
		p.savedQuery = nil
		p.cancelZoom()
		p.horizOffset = 0
		p.refreshFiltered()
	}
}

// setQueryProgrammatic replaces the query (used by Freeze/Toggle/etc).
func (p *peco) setQueryProgrammatic(q string) {
	p.query = []rune(q)
	p.cursor = 0
}

// ---------- termination ----------

func (p *peco) doFinish() {
	p.commitRange()
	if p.execCmd != "" {
		p.executeExec()
		return
	}
	p.done = true
	p.doneCode = 0
	p.cancelled = false
}

func (p *peco) doCancel() {
	if p.rangeActive {
		p.commitRange()
		return
	}
	p.done = true
	p.cancelled = true
	if p.onCancel == config.OnCancelError {
		p.doneCode = 1
	} else {
		p.doneCode = 0
	}
}

func (p *peco) selectionForOutput() []*Line {
	eff := p.effectiveSaved()
	if len(eff) > 0 {
		lines := make([]*Line, 0, len(eff))
		for _, l := range eff {
			lines = append(lines, l)
		}
		sort.Slice(lines, func(i, j int) bool { return lines[i].id < lines[j].id })
		return lines
	}
	if len(p.display) > 0 && p.selectedIdx >= 0 && p.selectedIdx < len(p.display) {
		return []*Line{p.display[p.selectedIdx]}
	}
	return nil
}

func (p *peco) executeExec() {
	selection := p.selectionForOutput()
	var sb strings.Builder
	for _, l := range selection {
		sb.WriteString(l.output)
		sb.WriteByte('\n')
	}
	if p.screen != nil {
		_ = p.screen.Suspend()
	}
