func rangeInterval(display []*Line, a, b int) map[int]*Line {
	out := make(map[int]*Line)
	if a < 0 || b < 0 || len(display) == 0 {
		return out
	}
	lo, hi := a, b
	if lo > hi {
		lo, hi = hi, lo
	}
	for i := lo; i <= hi && i < len(display); i++ {
		out[display[i].id] = display[i]
	}
	return out
}

// afterMovement updates an in-progress range selection following a
