			anchorPos = i
			break
		}
	}
	if anchorPos < 0 || len(p.display) == 0 {
		p.rangeContrib = make(map[int]*Line)
		return
	}
	p.rangeContrib = rangeInterval(p.display, anchorPos, p.selectedIdx)
}

func rangeInterval(display []*Line, a, b int) map[int]*Line {
	out := make(map[int]*Line)
	if a < 0 || b < 0 || len(display) == 0 {
		return out
	}
	lo, hi := a, b
	if lo > hi {
		lo, hi = hi, lo
	}
	for i := lo; i <= hi && i < len(display); i++ {
		out[display[i].id] = display[i]
	}
	return out
}

// afterMovement updates an in-progress range selection following a
// cursor movement. kind is "down", "up" or "other".
func (p *peco) afterMovement(kind string) {
	if !p.rangeActive {
		return
	}
	anchorPos := -1
	for i, l := range p.display {
		if l.id == p.rangeAnchorID {
			anchorPos = i
			break
		}
	}
	if anchorPos < 0 || len(p.display) == 0 {
		p.rangeContrib = make(map[int]*Line)
		return
	}
	cur := p.selectedIdx
	switch kind {
	case "up":
		if cur < anchorPos {
			p.rangeContrib = rangeInterval(p.display, cur, anchorPos)
		} else if cur > anchorPos {
			// Selecting upwards towards the anchor excludes the
			// line landed on.
			p.rangeContrib = rangeInterval(p.display, anchorPos, cur-1)
		} else {
			p.rangeContrib = make(map[int]*Line)
		}
	default:
		p.rangeContrib = rangeInterval(p.display, anchorPos, cur)
	}
}

func (p *peco) commitRange() {
	if !p.rangeActive {
		return
	}
	for id, l := range p.rangeContrib {
		p.saved[id] = l
	}
	p.rangeActive = false
	p.rangeContrib = nil
}

// ---------- query mutation ----------

// setQueryFromEditor applies an editor mutation; reruns the filter only
// when the text actually changed.
func (p *peco) applyQueryEdit(newQuery []rune, newCursor int) {
	old := p.queryString()
	p.query = newQuery
	if newCursor < 0 {
		newCursor = 0
	}
	if newCursor > len(newQuery) {
		newCursor = len(newQuery)
	}
	p.cursor = newCursor
	if string(newQuery) != old {
		p.hasSaved = false
		p.savedQuery = nil
		p.cancelZoom()
		p.horizOffset = 0
		p.refreshFiltered()
	}
}

// setQueryProgrammatic replaces the query (used by Freeze/Toggle/etc).
func (p *peco) setQueryProgrammatic(q string) {
	p.query = []rune(q)
	p.cursor = 0
}

// ---------- termination ----------

func (p *peco) doFinish() {
	p.commitRange()
	if p.execCmd != "" {
		p.executeExec()
		return
	}
	p.done = true
	p.doneCode = 0
	p.cancelled = false
}

func (p *peco) doCancel() {
	if p.rangeActive {
		p.commitRange()
		return
	}
	p.done = true
	p.cancelled = true
	if p.onCancel == config.OnCancelError {
		p.doneCode = 1
	} else {
		p.doneCode = 0
	}
}

func (p *peco) selectionForOutput() []*Line {
	eff := p.effectiveSaved()
	if len(eff) > 0 {
		lines := make([]*Line, 0, len(eff))
		for _, l := range eff {
			lines = append(lines, l)
		}
		sort.Slice(lines, func(i, j int) bool { return lines[i].id < lines[j].id })
		return lines
	}
	if len(p.display) > 0 && p.selectedIdx >= 0 && p.selectedIdx < len(p.display) {
		return []*Line{p.display[p.selectedIdx]}
	}
	return nil
}

func (p *peco) executeExec() {
	selection := p.selectionForOutput()
	var sb strings.Builder
	for _, l := range selection {
		sb.WriteString(l.output)
		sb.WriteByte('\n')
	}
	if p.screen != nil {
		_ = p.screen.Suspend()
	}
	cmd := exec.Command("/bin/sh", "-c", p.execCmd)
	cmd.Stdin = strings.NewReader(sb.String())
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	err := cmd.Run()
	if err != nil {
		p.done = true
		p.cancelled = true // suppress selection printing
		p.doneCode = 1
		p.returnErr = fmt.Errorf("failed to execute command: %w", err)
		return
	}
	if p.screen != nil {
		_ = p.screen.Resume()
	}
}

// ---------- timers ----------

func (p *peco) flashKeyseq() {
	p.keyseqGen++
	gen := p.keyseqGen
	if p.flashPostFunc != nil {
		go func() {
			time.Sleep(500 * time.Millisecond)
			p.flashPostFunc(gen)
		}()
	}
}

func (p *peco) setKeyseqDisplay(text string) {
	p.keyseqText = text
	p.statusMsg = ""
}
