// ---------- editor ----------

func deleteRunes(rs []rune, start, end int) []rune {
	out := make([]rune, 0, len(rs)-(end-start))
	out = append(out, rs[:start]...)
	out = append(out, rs[end:]...)
	return out
}

func (p *peco) editorForwardChar() {
	if p.cursor < len(p.query) {
		p.cursor++
	}
}

func (p *peco) editorBackwardChar() {
	if p.cursor > 0 {
		p.cursor--
	}
}

func (p *peco) editorForwardWord() {
	rs := p.query
	i := p.cursor
	if i >= len(rs) {
		return
	}
	if isSpaceRune(rs[i]) {
		for i < len(rs) && isSpaceRune(rs[i]) {
			i++
		}
	} else {
		for i < len(rs) && !isSpaceRune(rs[i]) {
			i++
		}
		for i < len(rs) && isSpaceRune(rs[i]) {
			i++
		}
	}
	p.cursor = i
}

func (p *peco) editorBackwardWord() {
	rs := p.query
	i := p.cursor
	if i <= 0 {
		return
	}
	i--
	for i >= 0 && isSpaceRune(rs[i]) {
		i--
	}
	for i >= 0 && !isSpaceRune(rs[i]) {
		i--
	}
	p.cursor = i + 1
}

func (p *peco) editorDeleteForwardWord() {
	rs := p.query
	if p.cursor >= len(rs) {
		return
	}
	i := p.cursor
	if isSpaceRune(rs[i]) {
		for i < len(rs) && isSpaceRune(rs[i]) {
			i++
		}
	} else {
		for i < len(rs) && !isSpaceRune(rs[i]) {
			i++
		}
	}
	p.applyQueryEdit(deleteRunes(rs, p.cursor, i), p.cursor)
}

func (p *peco) editorDeleteBackwardWord() {
	rs := p.query
	if p.cursor <= 0 {
		return
	}
	i := p.cursor
	if isSpaceRune(rs[i-1]) {
		for i > 0 && isSpaceRune(rs[i-1]) {
			i--
		}
	} else {
		for i > 0 && !isSpaceRune(rs[i-1]) {
			i--
		}
	}
	p.applyQueryEdit(deleteRunes(rs, i, p.cursor), i)
}

func (p *peco) editorEndOfFile() {
	if len(p.query) == 0 {
		p.doCancel()
		return
	}
	if p.cursor < len(p.query) {
		nq := deleteRunes(p.query, p.cursor, p.cursor+1)
		p.applyQueryEdit(nq, p.cursor)
	}
}

// ---------- cursor / selection ----------

func (p *peco) selectDown() {
	if len(p.display) == 0 {
		return
	}
	p.selectedIdx = (p.selectedIdx + 1) % len(p.display)
	p.afterMovement("down")
}

func (p *peco) selectUp() {
	if len(p.display) == 0 {
		return
	}
	p.selectedIdx = (p.selectedIdx - 1 + len(p.display)) % len(p.display)
	p.afterMovement("up")
}

func (p *peco) scrollPageDown() {
	if len(p.display) == 0 {
		return
	}
	p.selectedIdx += p.pageSizeForCalc()
	if p.selectedIdx >= len(p.display) {
		p.selectedIdx = 0
	}
	p.afterMovement("other")
}

func (p *peco) scrollPageUp() {
	if len(p.display) == 0 {
		return
	}
	p.selectedIdx -= p.pageSizeForCalc()
	if p.selectedIdx < 0 {
		p.selectedIdx = len(p.display) - 1
	}
	p.afterMovement("other")
}

func (p *peco) scrollFirst() {
	if len(p.display) == 0 {
		return
	}
	p.selectedIdx = 0
	p.afterMovement("other")
}

func (p *peco) scrollLast() {
	if len(p.display) == 0 {
		return
	}
	p.selectedIdx = len(p.display) - 1
	p.afterMovement("other")
}

func (p *peco) toggleSelection(_ bool) {
	if len(p.display) == 0 || p.selectedIdx >= len(p.display) {
		return
	}
	l := p.display[p.selectedIdx]
	if _, ok := p.saved[l.id]; ok {
		delete(p.saved, l.id)
	} else {
		p.saved[l.id] = l
	}
}

func (p *peco) selectVisible() {
	capacity := p.pageCapacity()
	if capacity <= 0 || len(p.display) == 0 {
		return
	}
	start := (p.selectedIdx / p.pageSizeForCalc()) * p.pageSizeForCalc()
	end := start + capacity
	if end > len(p.display) {
		end = len(p.display)
	}
	for i := start; i < end; i++ {
		p.saved[p.display[i].id] = p.display[i]
	}
}

func (p *peco) goToSelection(next bool) {
	eff := p.effectiveSaved()
	var savedIdx []int
	for i, l := range p.display {
		if _, ok := eff[l.id]; ok {
			savedIdx = append(savedIdx, i)
		}
	}
	if len(savedIdx) == 0 {
		p.statusMsg = "No Selection"
		p.keyseqText = ""
		return
	}
	if next {
		for _, idx := range savedIdx {
			if idx > p.selectedIdx {
				p.selectedIdx = idx
				p.statusMsg = "Next Selection"
				p.keyseqText = ""
				p.afterMovement("other")
				return
			}
		}
		p.selectedIdx = savedIdx[0]
		p.statusMsg = "Next Selection (first)"
		p.keyseqText = ""
		p.afterMovement("other")
		return
	}
	// Previous: search from just above the cursor down to index 1.
	for i := p.selectedIdx - 1; i >= 1; i-- {
		if _, ok := eff[p.display[i].id]; ok {
			p.selectedIdx = i
			p.statusMsg = "Previous Selection"
			p.keyseqText = ""
			p.afterMovement("other")
			return
		}
	}
	p.selectedIdx = savedIdx[len(savedIdx)-1]
	p.statusMsg = "Previous Selection (first)"
	p.keyseqText = ""
	p.afterMovement("other")
}

func (p *peco) toggleRangeMode() {
	if p.rangeActive {
		p.commitRange()
		return
	}
	if len(p.display) == 0 {
		return
	}
	p.rangeActive = true
	p.rangeAnchorID = p.display[p.selectedIdx].id
	p.rangeContrib = map[int]*Line{p.display[p.selectedIdx].id: p.display[p.selectedIdx]}
}

// ---------- horizontal scrolling ----------

func (p *peco) scrollRight() {
	w, _ := p.screenSize()
	if w <= 0 {
		return
	}
	maxOff := p.maxHorizOffset(w)
	p.horizOffset += w / 2
	if p.horizOffset > maxOff {
		p.horizOffset = maxOff
	}
}

func (p *peco) scrollLeft() {
	w, _ := p.screenSize()
	if w <= 0 {
		return
	}
	p.horizOffset -= w / 2
	if p.horizOffset < 0 {
		p.horizOffset = 0
	}
}

func (p *peco) maxHorizOffset(termW int) int {
	prefixW := p.prefixColumnWidth()
	maxW := 0
	for _, l := range p.display {
		cells := buildLineCells(p, l, nil, prefixW)
		if len(cells) > maxW {
			maxW = len(cells)
		}
	}
	contentW := prefixW + maxW
	if contentW-termW < 0 {
		return 0
	}
	return contentW - termW
}

func (p *peco) prefixColumnWidth() int {
	w := 0
	if p.selectionPrefix != "" {
		w += len(p.selectionPrefix) + 1
	}
	if p.inSingleJump || p.showJumpPrefix {
		w += 2
	}
	return w
}

// ---------- toggle query / view around ----------

func (p *peco) toggleQuery() {
	if p.hasSaved {
		p.query = p.savedQuery
		p.savedQuery = nil
		p.hasSaved = false
		p.cursor = 0
	} else {
		p.savedQuery = p.query
		p.hasSaved = true
		p.query = []rune{}
		p.cursor = 0
	}
	p.cancelZoom()
	p.refreshFiltered()
}

func (p *peco) viewAround() {
	var selectedLine *Line
	if len(p.display) > 0 && p.selectedIdx < len(p.display) {
		selectedLine = p.display[p.selectedIdx]
	}
	oldQuery := p.queryString()
	p.query = []rune{}
	p.cursor = 0
	if p.hasSaved && oldQuery == "" {
		// Editing while viewing around discards the toggled query
		// only if the visible query changed; here it does not.
	}
	if selectedLine != nil {
		base := p.baseLines()
		for i, l := range base {
			if l.id == selectedLine.id {
				p.selectedIdx = i
				break
			}
		}
	}
	p.cancelZoom()
	p.refreshFiltered()
	p.clampSelected()
	if selectedLine != nil {
		// After filtering (query cleared), keep the selection on the
		// same line if it is in the new display.
		for i, l := range p.display {
			if l.id == selectedLine.id {
				p.selectedIdx = i
				break
			}
		}
	}
}

// ---------- freeze / zoom ----------

func (p *peco) freezeResults() {
	snapshot := make([]*Line, len(p.filtered))
	copy(snapshot, p.filtered)
	wasZoomed := p.zoomed
	var savedDisplay []*Line
	if wasZoomed {
		savedDisplay = p.display
	}
	p.frozen = snapshot
	p.hasFrozen = true
	p.setQueryProgrammatic("")
	p.hasSaved = false
	p.savedQuery = nil
	p.horizOffset = 0
	// Recompute against the frozen base with the cleared query. Keep a
	// zoomed display intact until it is explicitly collapsed.
	p.refreshFilteredInternal(wasZoomed)
	if wasZoomed && savedDisplay != nil {
		p.display = savedDisplay
		p.clampSelected()
	}
	p.statusMsg = "Results frozen"
	p.keyseqText = ""
}

func (p *peco) unfreezeResults() {
	if !p.hasFrozen {
		p.statusMsg = "No frozen results"
		p.keyseqText = ""
		return
	}
	p.hasFrozen = false
	p.frozen = nil
	p.setQueryProgrammatic("")
	p.hasSaved = false
	p.savedQuery = nil
	p.cancelZoom()
	p.refreshFiltered()
	p.statusMsg = "Results unfrozen"
	p.keyseqText = ""
}

func (p *peco) zoomIn() {
	if p.zoomed {
		p.statusMsg = "Already zoomed in"
		p.keyseqText = ""
		return
	}
	if len(p.filtered) == 0 || (p.queryString() == "" && !p.hasFrozen) {
		p.statusMsg = "Nothing to zoom into"
		p.keyseqText = ""
		return
	}
	var current *Line
	if len(p.display) > 0 && p.selectedIdx < len(p.display) {
		current = p.display[p.selectedIdx]
	}
	p.preZoomIndex = p.selectedIdx
	source := p.store.snapshot()
	posInSource := make(map[int]int, len(source))
	for i, l := range source {
		posInSource[l.id] = i
	}
	matchedIDs := make(map[int]bool)
	include := make(map[int]bool)
	for _, l := range p.filtered {
		matchedIDs[l.id] = true
		if idx, ok := posInSource[l.id]; ok {
			for j := idx - 3; j <= idx+3; j++ {
				if j >= 0 && j < len(source) {
					include[j] = true
				}
			}
		}
	}
	var expanded []*Line
	context := make(map[int]bool)
	for i, l := range source {
		if include[i] {
			expanded = append(expanded, l)
			if !matchedIDs[l.id] {
				context[l.id] = true
			}
		}
	}
	// Lines without a source position (custom filter results) are
	// kept in place at the end of the expanded view.
	if len(expanded) == 0 {
		expanded = append(expanded, p.filtered...)
	} else {
		seen := make(map[int]bool)
		for _, l := range expanded {
			seen[l.id] = true
		}
		for _, l := range p.filtered {
			if _, ok := posInSource[l.id]; !ok && !seen[l.id] {
				expanded = append(expanded, l)
			}
		}
	}
	p.display = expanded
	p.displayContext = context
	p.zoomed = true
	if current != nil {
		for i, l := range p.display {
			if l.id == current.id {
				p.selectedIdx = i
				break
			}
		}
	}
	p.clampSelected()
}

func (p *peco) zoomOut() {
	if !p.zoomed {
		p.statusMsg = "Not zoomed in"
		p.keyseqText = ""
		return
	}
	p.zoomed = false
	p.displayContext = nil
	p.display = p.filtered
	p.selectedIdx = p.preZoomIndex
	p.clampSelected()
}

// ---------- action resolution ----------

func resolveAction(name string, custom map[string][]string, depth int) (actionFunc, error) {
	if depth >= 100 {
		return nil, fmt.Errorf("could not resolve %s: deep recursion", name)
	}
	if a, ok := builtinActions[name]; ok {
		return a, nil
	}
	list, ok := custom[name]
	if !ok {
		return nil, fmt.Errorf("could not resolve %s: no such action", name)
	}
	actions := make([]actionFunc, 0, len(list))
	for _, child := range list {
		a, err := resolveAction(child, custom, depth+1)
		if err != nil {
			return nil, err
		}
		actions = append(actions, a)
	}
	return func(p *peco) {
		for _, a := range actions {
			a(p)
			if p.done {
				return
			}
		}
	}, nil
}

