			}
			if i < len(p.query) {
				col += runewidth.RuneWidth(p.query[i])
			}
			continue
		}
		if i < len(p.query) {
			r := p.query[i]
			rw := runewidth.RuneWidth(r)
			if rw > 0 && col < fieldEnd && col >= 0 && col < w {
				scr.SetContent(col, y, r, nil, queryStyleT)
			}
			col += rw
		}
	}
	_ = cursorX
	// Filter information.
	p.drawText(infoX, y, w, info, p.styles.basic)
}

func (p *peco) cursorCellStyle() tcell.Style {
	st := p.styles.queryCursor
	if st.isPlain() {
