package main

import (
	"fmt"
	"strings"

	"github.com/gdamore/tcell/v2"
	runewidth "github.com/mattn/go-runewidth"
)

type lineCell struct {
	r       rune
	width   int
	style   styleDef
	matched bool
}

const jumpAlphabet = "asdfghjklzxcvbnmqwertyuiop"

func (p *peco) jumpPrefixVisible() bool {
	return p.inSingleJump || p.showJumpPrefix
}

// buildLineCells turns a line's display runes into terminal cells,
// expanding tabs relative to the absolute start column contentX.
func buildLineCells(p *peco, l *Line, matched []bool, contentX int) []lineCell {
	var cells []lineCell
	col := contentX
	for i, r := range l.displayRunes {
		st := p.cellBaseStyle(l, i)
		m := false
		if matched != nil && i < len(matched) {
			m = matched[i]
		}
		if m {
			st = st.withMatchedForeground(p.styles.matched)
		}
		if r == '\t' {
			n := 4 - (col % 4)
			if n == 0 {
				n = 4
			}
			for k := 0; k < n; k++ {
				cells = append(cells, lineCell{r: ' ', width: 1, style: st, matched: m})
				col++
			}
			continue
		}
		w := runewidth.RuneWidth(r)
		if w == 0 {
			continue
		}
		cells = append(cells, lineCell{r: r, width: w, style: st, matched: m})
		col += w
	}
	return cells
}

// cellBaseStyle gives the unmatched style for a display rune.
func (p *peco) cellBaseStyle(l *Line, idx int) styleDef {
	// For non-basic lines the caller replaces the base entirely; this
	// function returns the Basic/ANSI style used as the starting point.
	if p.ansiEnabled && l.ansiStyles != nil && idx < len(l.ansiStyles) {
		return l.ansiStyles[idx]
	}
	return p.styles.basic
}

// lineBaseStyle determines the base styleDef for a displayed line given
// its state. It returns the style and whether ANSI per-character
// styles should be used (only for plain lines).
func (p *peco) lineBase(l *Line, isCurrent, isSaved, isContext bool) (styleDef, bool) {
	if p.selectionPrefix != "" {
		if isContext && !isCurrent && !isSaved {
			return p.styles.context, false
		}
		return p.styles.basic, p.ansiEnabled && l.ansiStyles != nil
	}
	switch {
	case isCurrent:
		return p.styles.selected, false
	case isSaved:
		return p.styles.savedSelection, false
	case isContext:
		return p.styles.context, false
	default:
		return p.styles.basic, p.ansiEnabled && l.ansiStyles != nil
	}
}

func (p *peco) draw() {
	if p.screen == nil {
		return
	}
	scr := p.screen
	w, h := scr.Size()
	if w < 0 {
		w = 0
	}
	if h < 0 {
		h = 0
	}
	vh := p.virtualHeight()
	yOff := 0
	if p.height != nil {
		total := p.inlineTotalRows(h)
		yOff = h - total
		if yOff < 0 {
			yOff = 0
		}
		p.inlineTop = yOff
	}
	scr.SetStyle(p.styles.basic.toTcell())
	scr.Clear()

	// Layout rows in virtual coordinates.
	queryRow, listTop, listRows, statusRow := p.layoutRows(vh)

	// Status row (drawn first so other components win overlaps).
	if !p.suppressStatus || true {
		p.drawStatusRow(w, yOff+statusRow)
	}
	// List.
	p.drawList(w, yOff, listTop, listRows)
	// Query line.
	p.drawQuery(w, yOff+queryRow)

	// Cursor.
	cx, cy := p.cursorPosition(yOff + queryRow)
	scr.ShowCursor(cx, cy)
	scr.Show()
}

func (p *peco) layoutRows(vh int) (queryRow, listTop, listRows, statusRow int) {
	statusRow = vh - 1
	switch p.layout {
	case "bottom-up", "top-down-query-bottom":
		queryRow = vh - 2
		listTop = 0
		listRows = vh - 2
	default: // top-down
		queryRow = 0
		listTop = 1
		listRows = vh - 2
	}
	if listRows < 0 {
		listRows = 0
	}
	return
}

func (p *peco) drawStatusRow(w, y int) {
	if p.screen == nil || y < 0 {
		return
	}
	_, h := p.screen.Size()
	if y >= h {
		return
	}
	scr := p.screen
	base := p.styles.basic.toTcell()
	for x := 0; x < w; x++ {
		scr.SetContent(x, y, ' ', nil, base)
	}
	if p.suppressStatus {
		return
	}
	text := p.statusMsg
	if p.keyseqText != "" {
		text = p.keyseqText
	}
	if text == "" {
		return
	}
	style := p.styles.basic
	style.bold = true
	style.reverse = true
	st := style.toTcell()
	tw := stringDisplayWidth(text)
	x := w - tw
	runes := []rune(text)
	col := x
	for _, r := range runes {
		rw := runewidth.RuneWidth(r)
		if rw == 0 {
			continue
		}
		if col >= 0 && col < w {
			scr.SetContent(col, y, r, nil, st)
		}
		col += rw
	}
}

func (p *peco) pageStart() int {
	ps := p.pageSizeForCalc()
	if len(p.display) == 0 {
		return 0
	}
	return (p.selectedIdx / ps) * ps
}

func (p *peco) drawList(w, yOff, listTop, listRows int) {
	scr := p.screen
	capacity := p.pageCapacity()
	if capacity <= 0 || listRows <= 0 {
		return
	}
	start := p.pageStart()
	// Build the page slice.
	var page []*Line
	if start < len(p.display) {
		end := start + capacity
		if end > len(p.display) {
			end = len(p.display)
		}
		page = p.display[start:end]
	}
	effSaved := p.effectiveSaved()
	// Draw each virtual list row.
	for row := 0; row < listRows; row++ {
		y := yOff + listTop + row
		_, sh := scr.Size()
		if y < 0 || y >= sh {
			continue
		}
		// Resolve which page element (if any) belongs on this row.
		var line *Line
		displayIdx := -1
		if p.layout == "bottom-up" {
			// Items are anchored to the bottom of the list area
			// and reversed.
			n := len(page)
			// Row positions listTop..listTop+listRows-1; the last
			// rows hold the page.
			posInArea := row
			// index from the bottom
			fromBottom := listRows - 1 - posInArea
			if fromBottom < n {
				revIdx := n - 1 - fromBottom
				if revIdx >= 0 && revIdx < n {
					line = page[revIdx]
					displayIdx = start + revIdx
				}
			}
		} else {
			if row < len(page) {
				line = page[row]
				displayIdx = start + row
			}
		}
		if line == nil {
			continue
		}
		p.drawLineRow(w, y, line, displayIdx, start, effSaved)
	}
}

func (p *peco) drawLineRow(w, y int, line *Line, displayIdx, pageStart int, effSaved map[int]*Line) {
	scr := p.screen
	isCurrent := displayIdx == p.selectedIdx
	_, isSaved := effSaved[line.id]
	isContext := false
	if p.displayContext != nil {
		isContext = p.displayContext[line.id]
	}
	base, useANSI := p.lineBase(line, isCurrent, isSaved, isContext)
	baseT := base.toTcell()
	// Fill the row with the base style.
	for x := 0; x < w; x++ {
		scr.SetContent(x, y, ' ', nil, baseT)
	}
	x := 0
	// Selection prefix.
	if p.selectionPrefix != "" {
		prefW := len(p.selectionPrefix) + 1
		if isCurrent {
			col := 0
			for _, r := range p.selectionPrefix {
				rw := runewidth.RuneWidth(r)
				if rw > 0 && col < w {
					scr.SetContent(col, y, r, nil, baseT)
				}
				col += rw
			}
		} else if isSaved {
			if w > 0 {
				scr.SetContent(0, y, '*', nil, baseT)
			}
		}
		x += prefW
	}
	// Single-key-jump prefix.
	if p.jumpPrefixVisible() {
		rel := displayIdx - pageStart
		var ch rune = ' '
		if rel >= 0 && rel < len(jumpAlphabet) {
			ch = rune(jumpAlphabet[rel])
		}
		hintStyle := base
		hintStyle.bold = true
		hintStyle.reverse = true
		if x < w {
			scr.SetContent(x, y, ch, nil, hintStyle.toTcell())
		}
		x++
		if x < w {
			scr.SetContent(x, y, ' ', nil, baseT)
		}
		x++
	}
	contentX := x
	var matchedFlags []bool
	if p.matched != nil {
		matchedFlags = p.matched[line.id]
	}
	// Build cells with the correct per-character styles.
	cells := p.buildCellsForLine(line, matchedFlags, base, useANSI, isCurrent, isSaved, isContext, contentX)
	// Apply the horizontal offset in columns.
	col := 0
	cx := contentX
	for _, cell := range cells {
		if col+cell.width <= p.horizOffset {
			col += cell.width
			continue
		}
		if col < p.horizOffset {
			// A wide character straddling the offset: show a space.
			if cx < w {
				scr.SetContent(cx, y, ' ', nil, cell.style.toTcell())
				cx++
			}
			col += cell.width
			continue
		}
		if cx >= w {
			break
		}
		scr.SetContent(cx, y, cell.r, nil, cell.style.toTcell())
		cx += cell.width
		col += cell.width
	}
}

// buildCellsForLine produces cells with effective styles for a line.
func (p *peco) buildCellsForLine(line *Line, matched []bool, base styleDef, useANSI, isCurrent, isSaved, isContext bool, contentX int) []lineCell {
	var cells []lineCell
	col := contentX
	for i, r := range line.displayRunes {
		var st styleDef
		if useANSI {
			st = p.cellBaseStyle(line, i)
		} else {
			st = base
		}
		m := false
		if matched != nil && i < len(matched) {
			m = matched[i]
		}
		if m {
			st = st.withMatchedForeground(p.styles.matched)
		}
		if r == '\t' {
			n := 4 - (col % 4)
			for k := 0; k < n; k++ {
				cells = append(cells, lineCell{r: ' ', width: 1, style: st, matched: m})
				col++
			}
			continue
		}
		rw := runewidth.RuneWidth(r)
		if rw == 0 {
			continue
		}
		cells = append(cells, lineCell{r: r, width: rw, style: st, matched: m})
		col += rw
	}
	return cells
}

func (p *peco) drawQuery(w, y int) {
	scr := p.screen
	_, sh := scr.Size()
	if y < 0 || y >= sh {
		// Still may be partially visible if y == -1? It is not.
		if y != -1 {
			return
		}
		return
	}
	basicT := p.styles.basic.toTcell()
	for x := 0; x < w; x++ {
		scr.SetContent(x, y, ' ', nil, basicT)
	}
	// Right-hand filter information.
	capacity := p.pageSizeForCalc()
	count := len(p.display)
	totalPages := 1
	if count > 0 {
		totalPages = (count + capacity - 1) / capacity
	}
	curPage := 1
	if count > 0 {
		curPage = p.selectedIdx/capacity + 1
	}
	info := fmt.Sprintf("%s [%d (%d/%d)]", p.currentFilterEntry().name, count, curPage, totalPages)
	infoW := stringDisplayWidth(info)
	infoX := w - infoW

	// Query field: from just after the prompt to the info start.
	promptW := stringDisplayWidth(p.prompt)
	p.drawText(0, y, w, p.prompt, p.styles.prompt)
	// Query text (including its leading separator space) is drawn
	// with the Query style across the field.
	fieldStart := promptW
	fieldEnd := infoX
	if fieldEnd < fieldStart {
		fieldEnd = fieldStart
	}
	queryStyleT := p.styles.query.toTcell()
	for x := fieldStart; x < fieldEnd && x < w; x++ {
		scr.SetContent(x, y, ' ', nil, queryStyleT)
	}
	// Draw query runes.
	qx := fieldStart + 1 // separator space
	col := qx
	// The character under the cursor (or a space past the end).
	cursorX := qx
	for i := 0; i <= len(p.query); i++ {
		if i == p.cursor {
			cursorX = col
			var ch rune = ' '
			if i < len(p.query) {
				ch = p.query[i]
			}
			cst := p.cursorCellStyle()
			if col < fieldEnd && col >= 0 && col < w {
				scr.SetContent(col, y, ch, nil, cst)
			}
			if i < len(p.query) {
				col += runewidth.RuneWidth(p.query[i])
			}
			continue
		}
		if i < len(p.query) {
			r := p.query[i]
			rw := runewidth.RuneWidth(r)
			if rw > 0 && col < fieldEnd && col >= 0 && col < w {
				scr.SetContent(col, y, r, nil, queryStyleT)
			}
			col += rw
		}
	}
	_ = cursorX
	// Filter information.
	p.drawText(infoX, y, w, info, p.styles.basic)
}

func (p *peco) cursorCellStyle() tcell.Style {
	st := p.styles.queryCursor
	if st.isPlain() {
		// An unspecified cursor style is shown reversed.
		st = styleDef{reverse: true}
	}
	return st.toTcell()
}

func (p *peco) drawText(x, y, w int, text string, st styleDef) {
	if y < 0 {
		return
	}
	_, sh := p.screen.Size()
	if y >= sh {
		return
	}
	col := x
	t := st.toTcell()
	for _, r := range text {
		rw := runewidth.RuneWidth(r)
		if rw == 0 {
			continue
		}
		if col >= 0 && col < w {
			p.screen.SetContent(col, y, r, nil, t)
		}
		col += rw
	}
}

func (p *peco) cursorPosition(queryY int) (int, int) {
	promptW := stringDisplayWidth(p.prompt)
	x := promptW + 1
	for i := 0; i < p.cursor && i < len(p.query); i++ {
		x += runewidth.RuneWidth(p.query[i])
	}
	return x, queryY
}

