)

// setupResult carries the configured peco and any early exit.
type setupState struct {
	p *peco
}

// parseAndSetup performs command line parsing, configuration loading
// and application. It returns (peco, handled, exitCode, error) where
// handled means the program should stop (help/version/early shortcut).
func loadConfig(opts *options) (*config.Config, error) {
	var cfg *config.Config
	if opts.rcfile != "" {
		c, err := config.ReadFile(opts.rcfile)
		if err != nil {
			return nil, fmt.Errorf("failed to setup peco: failed to setup configuration: failed to read config file: %w", err)
		}
		cfg = c
	} else {
		cfg = &config.Config{}
		if path := config.Locate(); path != "" {
			c, err := config.ReadFile(path)
			if err != nil {
				return nil, fmt.Errorf("failed to setup peco: failed to setup configuration: failed to read config file: %w", err)
			}
			cfg = c
		}
	}
	return cfg, nil
}

// applyConfig builds the peco state from options + config file.
func applyConfig(opts *options, cfg *config.Config) (*peco, error) {
	p := &peco{
		opts:      opts,
		cfg:       cfg,
		styles:    defaultStyleSet(),
		saved:     make(map[int]*Line),
		matched:   make(map[int][]bool),
		onCancel:  config.OnCancelSuccess,
		firstRefresh: true,
	}

	// OnCancel.
	if opts.onCancel != "" {
		v, err := config.ValidateOnCancel(opts.onCancel)
		if err != nil {
			return nil, fmt.Errorf("invalid --on-cancel value: %w", err)
		}
		p.onCancel = v
	} else if cfg.OnCancel != "" {
		p.onCancel = cfg.OnCancel
	}

	// Height.
	heightStr := opts.height
	if heightStr == "" {
		heightStr = cfg.Height
	}
	if heightStr != "" {
		hs, err := parseHeight(heightStr)
		if err != nil {
			return nil, fmt.Errorf("failed to parse height specification: %w", err)
		}
		p.height = hs
	}

	// Build the filter list (built-ins first, then custom filters
	// sorted by name).
	p.filters = []filterEntry{
		{name: "IgnoreCase"}, {name: "CaseSensitive"}, {name: "SmartCase"},
		{name: "IRegexp"}, {name: "Regexp"}, {name: "Fuzzy"},
	}
	if len(cfg.CustomFilter) > 0 {
		names := make([]string, 0, len(cfg.CustomFilter))
		for name := range cfg.CustomFilter {
			names = append(names, name)
		}
		sort.Strings(names)
		for _, name := range names {
			fc := cfg.CustomFilter[name]
			p.filters = append(p.filters, filterEntry{
				name: name,
				custom: &customFilterDef{
					name:            name,
					cmd:             fc.Cmd,
					args:            fc.Args,
					bufferThreshold: fc.BufferThreshold,
				},
			})
		}
	}

	// Styles.
	if len(cfg.Style.Present) > 0 {
		defs := make(map[string][]string)
		if cfg.Style.Present["Basic"] {
			defs["Basic"] = cfg.Style.Basic
		}
		if cfg.Style.Present["SavedSelection"] {
			defs["SavedSelection"] = cfg.Style.SavedSelection
		}
		if cfg.Style.Present["Selected"] {
			defs["Selected"] = cfg.Style.Selected
		}
		if cfg.Style.Present["Query"] {
			defs["Query"] = cfg.Style.Query
		}
		if cfg.Style.Present["QueryCursor"] {
			defs["QueryCursor"] = cfg.Style.QueryCursor
		}
		if cfg.Style.Present["Matched"] {
			defs["Matched"] = cfg.Style.Matched
		}
		if cfg.Style.Present["Prompt"] {
			defs["Prompt"] = cfg.Style.Prompt
		}
		if cfg.Style.Present["Context"] {
			defs["Context"] = cfg.Style.Context
		}
		p.styles.applyConfig(defs)
	}

	// Keymap.
	bindings, err := buildKeymap(cfg)
	if err != nil {
		return nil, fmt.Errorf("failed to populate keymap: %w", err)
	}
	p.keymap = bindings

	// Initial filter.
	filterName := opts.initialFilter
	if filterName == "" {
		filterName = cfg.InitialFilter
	}
	if filterName == "" {
		filterName = "IgnoreCase"
	}
	idx := -1
	for i, f := range p.filters {
		if f.name == filterName {
			idx = i
			break
		}
	}
	if idx < 0 {
		return nil, fmt.Errorf("failed to populate initial filter: failed to set filter: specified filter was not found")
	}
	p.currentFilter = idx

	// Miscellaneous settings.
	p.prompt = opts.prompt
	if p.prompt == "" {
		p.prompt = cfg.Prompt
	}
	if p.prompt == "" {
		p.prompt = "QUERY>"
	}
	p.layout = opts.layout
	if p.layout == "" {
		p.layout = cfg.Layout
	}
	if p.layout == "" {
		p.layout = "top-down"
	}
	p.selectionPrefix = opts.selectionPrefix
	if p.selectionPrefix == "" {
		p.selectionPrefix = cfg.SelectionPrefix
	}
	p.fuzzyLongest = cfg.FuzzyLongestSort
	p.sticky = cfg.StickySelection
	p.suppressStatus = cfg.SuppressStatusMsg
	p.ansiEnabled = cfg.ANSI || opts.ansi
	p.nullSep = opts.null
	p.showJumpPrefix = cfg.SingleKeyJump.ShowPrefix
	p.bufferSize = opts.bufferSize
	p.execCmd = opts.exec
	p.query = []rune(opts.query)
	p.cursor = len(p.query)
	return p, nil
}

// buildKeymap creates the full key binding table.
type keymap struct {
	bindings map[string]actionFunc
	prefixes map[string]bool
}

func buildKeymap(cfg *config.Config) (*keymap, error) {
	km := &keymap{
		bindings: make(map[string]actionFunc),
		prefixes: make(map[string]bool),
	}
	add := func(spec string, a actionFunc) {
		seq, err := parseKeySequence(spec)
		if err != nil {
			return
		}
		km.bind(seq, a)
	}
	defaults := [][2]string{
		{"Esc", "peco.Cancel"},
		{"C-c", "peco.Cancel"},
		{"Enter", "peco.Finish"},
		{"C-f", "peco.ForwardChar"},
		{"C-a", "peco.BeginningOfLine"},
		{"C-b", "peco.BackwardChar"},
		{"C-d", "peco.DeleteForwardChar"},
		{"C-e", "peco.EndOfLine"},
		{"C-k", "peco.KillEndOfLine"},
		{"C-u", "peco.KillBeginningOfLine"},
		{"BS", "peco.DeleteBackwardChar"},
		{"C-8", "peco.DeleteBackwardChar"},
