		if cfg.Style.Present["Selected"] {
			defs["Selected"] = cfg.Style.Selected
		}
		if cfg.Style.Present["Query"] {
			defs["Query"] = cfg.Style.Query
		}
		if cfg.Style.Present["QueryCursor"] {
			defs["QueryCursor"] = cfg.Style.QueryCursor
		}
		if cfg.Style.Present["Matched"] {
			defs["Matched"] = cfg.Style.Matched
		}
		if cfg.Style.Present["Prompt"] {
			defs["Prompt"] = cfg.Style.Prompt
		}
		if cfg.Style.Present["Context"] {
			defs["Context"] = cfg.Style.Context
		}
		p.styles.applyConfig(defs)
	}

	// Keymap.
	bindings, err := buildKeymap(cfg)
	if err != nil {
		return nil, fmt.Errorf("failed to populate keymap: %w", err)
	}
	p.keymap = bindings

	// Initial filter.
	filterName := opts.initialFilter
	if filterName == "" {
		filterName = cfg.InitialFilter
	}
	if filterName == "" {
		filterName = "IgnoreCase"
	}
	idx := -1
	for i, f := range p.filters {
		if f.name == filterName {
			idx = i
			break
		}
	}
	if idx < 0 {
		return nil, fmt.Errorf("failed to populate initial filter: failed to set filter: specified filter was not found")
	}
	p.currentFilter = idx

	// Miscellaneous settings.
	p.prompt = opts.prompt
	if p.prompt == "" {
		p.prompt = cfg.Prompt
	}
	if p.prompt == "" {
		p.prompt = "QUERY>"
	}
	p.layout = opts.layout
	if p.layout == "" {
		p.layout = cfg.Layout
	}
	if p.layout == "" {
		p.layout = "top-down"
	}
	p.selectionPrefix = opts.selectionPrefix
	if p.selectionPrefix == "" {
		p.selectionPrefix = cfg.SelectionPrefix
	}
	p.fuzzyLongest = cfg.FuzzyLongestSort
	p.sticky = cfg.StickySelection
	p.suppressStatus = cfg.SuppressStatusMsg
	p.ansiEnabled = cfg.ANSI || opts.ansi
	p.nullSep = opts.null
	p.showJumpPrefix = cfg.SingleKeyJump.ShowPrefix
	p.bufferSize = opts.bufferSize
	p.execCmd = opts.exec
	p.query = []rune(opts.query)
	p.cursor = len(p.query)
	return p, nil
}

// buildKeymap creates the full key binding table.
type keymap struct {
	bindings map[string]actionFunc
	prefixes map[string]bool
}

func buildKeymap(cfg *config.Config) (*keymap, error) {
	km := &keymap{
		bindings: make(map[string]actionFunc),
		prefixes: make(map[string]bool),
	}
	add := func(spec string, a actionFunc) {
		seq, err := parseKeySequence(spec)
		if err != nil {
			return
		}
		km.bind(seq, a)
	}
	defaults := [][2]string{
		{"Esc", "peco.Cancel"},
		{"C-c", "peco.Cancel"},
		{"Enter", "peco.Finish"},
		{"C-f", "peco.ForwardChar"},
		{"C-a", "peco.BeginningOfLine"},
		{"C-b", "peco.BackwardChar"},
		{"C-d", "peco.DeleteForwardChar"},
		{"C-e", "peco.EndOfLine"},
		{"C-k", "peco.KillEndOfLine"},
		{"C-u", "peco.KillBeginningOfLine"},
		{"BS", "peco.DeleteBackwardChar"},
		{"C-8", "peco.DeleteBackwardChar"},
		{"C-w", "peco.DeleteBackwardWord"},
		{"C-g", "peco.SelectNone"},
		{"C-n", "peco.SelectDown"},
		{"C-p", "peco.SelectUp"},
		{"C-r", "peco.RotateFilter"},
		{"C-t", "peco.ToggleQuery"},
		{"C-Space", "peco.ToggleSelectionAndSelectNext"},
		{"ArrowUp", "peco.SelectUp"},
		{"ArrowDown", "peco.SelectDown"},
		{"ArrowLeft", "peco.ScrollPageUp"},
		{"ArrowRight", "peco.ScrollPageDown"},
		{"Pgup", "peco.ScrollPageUp"},
		{"Pgdn", "peco.ScrollPageDown"},
		{"Home", "peco.ScrollFirstItem"},
		{"End", "peco.ScrollLastItem"},
	}
	custom := cfg.Action
	for _, d := range defaults {
		a, err := resolveAction(d[1], custom, 0)
		if err == nil {
			add(d[0], a)
		}
	}
	// Custom bindings.
	for spec, actionName := range cfg.Keymap {
		seq, err := parseKeySequence(spec)
		if err != nil {
			return nil, fmt.Errorf("failed to apply key bindings: unknown key %s: %w", spec, err)
		}
		a, err := resolveAction(actionName, custom, 0)
		if err != nil {
			return nil, fmt.Errorf("failed to apply key bindings: failed to resolve action name %s: %w", actionName, err)
		}
		km.bind(seq, a)
	}
	return km, nil
}

func (km *keymap) bind(seq []keyVal, a actionFunc) {
	km.bindings[seqKey(seq)] = a
	for i := 1; i < len(seq); i++ {
		km.prefixes[seqKey(seq[:i])] = true
	}
}

func (km *keymap) lookup(seq []keyVal) (actionFunc, bool, bool) {
	a, exact := km.bindings[seqKey(seq)]
	return a, exact, km.prefixes[seqKey(seq)]
}

// ---------- input ----------

type inputSource struct {
	reader io.Reader
	closer io.Closer
}

func setupInputSource(opts *options) (*inputSource, error) {
	if len(opts.args) > 0 {
		f, err := os.Open(opts.args[0])
		if err != nil {
			return nil, fmt.Errorf("failed to open file for input: %w", err)
		}
		return &inputSource{reader: f, closer: f}, nil
	}
	if isCharDevice(os.Stdin) {
		return nil, fmt.Errorf("you must supply something to work with via filename or stdin")
	}
	return &inputSource{reader: os.Stdin}, nil
}

func isCharDevice(f *os.File) bool {
	fi, err := f.Stat()
	if err != nil {
		return false
	}
	return fi.Mode()&os.ModeCharDevice != 0
}

// startReader launches the line-reading goroutine.
func startReader(src *inputSource, p *peco, store *inputStore) {
	go func() {
		maxScan := p.cfg.MaxScanBufferSize
		if maxScan <= 0 {
			maxScan = 256
		}
		maxBytes := maxScan * 1024
		scanner := bufio.NewScanner(src.reader)
		initCap := 4096
		if maxBytes < initCap {
			initCap = maxBytes
		}
		if initCap < 1 {
			initCap = 1
		}
		scanner.Buffer(make([]byte, 0, initCap), maxBytes)
		scanner.Split(bufio.ScanLines)
		for scanner.Scan() {
			text := scanner.Text()
			line := newLine(text, p.nullSep, p.ansiEnabled)
			store.mu.Lock()
			store.lines = append(store.lines, line)
			if p.bufferSize > 0 && len(store.lines) > p.bufferSize {
				store.lines = store.lines[len(store.lines)-p.bufferSize:]
			}
			store.mu.Unlock()
			notifyInput(p)
		}
		store.mu.Lock()
		store.done = true
		store.mu.Unlock()
		notifyInput(p)
		if src.closer != nil {
			src.closer.Close()
		}
	}()
}

var inputNotifyCounter int64

func notifyInput(p *peco) {
	if p.inputPostFunc == nil {
		return
	}
	if atomic.CompareAndSwapInt32(&p.inputPending, 0, 1) {
		p.inputPostFunc()
	}
}

// createScreen creates (but does not initialise) the terminal screen.
func createScreen(heightMode bool) (tcell.Screen, error) {
	if !heightMode {
		s, err := tcell.NewScreen()
		if err != nil {
			return nil, err
		}
		return s, nil
	}
	// Probe with the standard constructor for identical errors.
	if _, err := tcell.NewScreen(); err != nil {
		return nil, err
	}
	ti, err := tcell.LookupTerminfo(os.Getenv("TERM"))
	if err != nil {
		return nil, err
	}
	tiCopy := *ti
	tiCopy.EnterCA = ""
	tiCopy.ExitCA = ""
	s, err := tcell.NewTerminfoScreenFromTtyTerminfo(nil, &tiCopy)
	if err != nil {
		return nil, err
	}
	_ = terminfo.AddTerminfo
	return s, nil
}

var _ = time.Now
var _ = strings.TrimSpace
EOF
