package main

import (
	"strings"
	"sync/atomic"

	"github.com/gdamore/tcell/v2"
)

type inputEvent struct{ tcell.EventTime }
func (e *inputEvent) When() (t interface{}) { return nil }

type flashEvent struct {
	gen int
}

// handleKeyEvent processes one key. It returns after updating state.
func (p *peco) handleKey(k keyVal) {
	// Single-key jump mode intercepts rune keys.
	if p.inSingleJump && k.kind == keyRuneKind && k.mods == 0 {
		r := k.r
		if idx := strings.IndexRune(jumpAlphabet, r); idx >= 0 {
			if idx < len(p.display) {
				p.selectedIdx = idx
				p.afterMovement("other")
			}
			p.inSingleJump = false
			p.doFinish()
			return
		}
		// Other runes are ignored in this mode.
		return
	}

	p.pending = append(p.pending, k)
	text := seqDisplayText(p.pending)
	action, exact, hasPrefix := p.keymap.lookup(p.pending)

	if exact && !hasPrefix {
		p.pending = nil
		p.setKeyseqDisplay(text)
		action(p)
		p.afterAction(action, true)
		return
	}
	if hasPrefix {
		// Wait for the rest of the sequence.
		p.setKeyseqDisplay(text)
		return
	}
	// No match.
	p.pending = nil
	if k.kind == keyRuneKind {
		if k.mods&modAlt != 0 {
			// Alt+rune falls back to inserting the rune.
			p.insertRune(k.r)
			return
		}
		if k.mods == 0 {
			p.insertRune(k.r)
			return
		}
	}
	// A special/control key with no binding: just show the failed
	// sequence briefly.
	p.setKeyseqDisplay(text)
	p.flashKeyseq()
}

func (p *peco) afterAction(_ actionFunc, _ bool) {
	// If the action set a status message it has already replaced the
	// key sequence display. If it re-ran the filter, the status has
	// been cleared. Otherwise the key sequence flashes briefly.
	if p.statusMsg != "" {
		p.keyseqText = ""
		return
	}
	if p.keyseqText != "" {
		p.flashKeyseq()
	}
}

func seqDisplayText(seq []keyVal) string {
	parts := make([]string, len(seq))
	for i, k := range seq {
		parts[i] = k.String()
	}
	return strings.Join(parts, " ")
}

func (p *peco) insertRune(r rune) {
	if r < 0x20 || r == 0x7f {
		return
	}
	nq := make([]rune, 0, len(p.query)+1)
	nq = append(nq, p.query[:p.cursor]...)
	nq = append(nq, r)
	nq = append(nq, p.query[p.cursor:]...)
	p.keyseqText = ""
	p.applyQueryEdit(nq, p.cursor+1)
}

// runEventLoop is the main UI loop.
func (p *peco) runEventLoop() {
	scr := p.screen
	// Input notifications and keyseq flash timers post events here.
	p.inputPostFunc = func() {
		_ = scr.PostEvent(tcell.NewEventInterrupt("input"))
	}
	p.flashPostFunc = func(gen int) {
		_ = scr.PostEvent(tcell.NewEventInterrupt(flashEventData{gen: gen}))
	}
	atomic.StoreInt32(&p.inputPending, 0)

	// Initial draw with the waiting message, then the first results.
	if !p.suppressStatus {
		p.statusMsg = "Waiting for input..."
	}
	p.draw()
	p.refreshFiltered()
	if p.firstRefresh {
		p.firstRefresh = false
		if p.opts.query == "" {
			p.selectedIdx = p.opts.initialIndex
			p.clampSelected()
		} else {
			p.selectedIdx = 0
			p.clampSelected()
		}
	}
	p.draw()
	if p.store.isDone() {
		if p.evaluateShortcuts() {
			return
		}
	}

	for !p.done {
		ev := scr.PollEvent()
		switch ev := ev.(type) {
		case *tcell.EventKey:
			if k, ok := keyFromEvent(ev); ok {
				p.handleKey(k)
			}
		case *tcell.EventMouse:
			if k, ok := mouseKeyFromEvent(ev); ok {
				p.handleKey(k)
			}
		case *tcell.EventResize:
			scr.Sync()
		case *tcell.EventPaste:
			// Paste markers are ignored; content arrives as keys.
		case *tcell.EventInterrupt:
			switch data := ev.Data().(type) {
			case string:
				if data == "input" {
					atomic.StoreInt32(&p.inputPending, 0)
					p.refreshFiltered()
					if p.store.isDone() {
						if p.evaluateShortcuts() {
							// fall through to final draw
						}
					}
				}
			case flashEventData:
				if data.gen == p.keyseqGen && p.statusMsg == "" {
					p.keyseqText = ""
				}
			}
		}
		if p.requestSync {
			p.requestSync = false
			scr.Sync()
		}
		if p.done {
			// One final draw (which shows the last key, like the
			// original) before tearing the screen down.
			p.draw()
			return
		}
		p.draw()
	}
}

type flashEventData struct{ gen int }

// evaluateShortcuts applies --exit-0/--select-1/--select-all when the
// input is complete. It reports whether the program should exit.
func (p *peco) evaluateShortcuts() bool {
	count := p.store.count()
	if p.opts.exit0 && count == 0 {
		p.done = true
		p.doneCode = 1
		p.cancelled = true
		return true
	}
	if p.opts.select1 {
		if count == 1 {
			lines := p.store.snapshot()
			p.directResult = []*Line{lines[0]}
			p.done = true
			p.doneCode = 0
			p.cancelled = false
			return true
		}
		return false
	}
	if p.opts.selectAll {
		p.refreshFiltered()
		for _, l := range p.filtered {
			p.saved[l.id] = l
		}
		p.done = true
		p.doneCode = 0
		p.cancelled = false
		return true
	}
	return false
}
