	out := s
	out.hasFg = m.hasFg
	out.fg = m.fg
	out.bold = m.bold
	out.underline = m.underline
	out.reverse = m.reverse
	// bgBold belongs to the background side and is preserved.
	return out
}''','''// withMatchedForeground returns the style obtained by replacing the
// foreground side of s with m's. The background colours are combined
// with a bitwise OR (a quirk of the original style composition), and
// the background-bold attribute is set if either side has it.
func (s styleDef) withMatchedForeground(m styleDef) styleDef {
	out := s
	out.hasFg = m.hasFg
	out.fg = m.fg
	out.bold = m.bold
	out.underline = m.underline
	out.reverse = m.reverse
	if m.hasBg {
		if out.hasBg {
			out.bg = out.bg | m.bg
		} else {
			out.bg = m.bg
		}
		out.hasBg = true
	}
	out.bgBold = out.bgBold || m.bgBold
	return out
}''')
